impl Capacity for ComputeSigAdvCapacity{
	fn can_satisfy(&self, r_other: &Arc<dyn Capacity + Send + Sync>) -> bool{
		let other = r_other.as_any().downcast_ref::<ComputeSigAdvCapacity>()
			.expect("downcast err"); 

		self.subsigs_cs >= other.subsigs_cs &&
		self.subsigs_igc >= other.subsigs_igc &&
		self.sigs >= other.sigs &&
		self.max_nibble_len>= other.max_nibble_len &&
		self.basis_pats_in_trace_cs>= other.basis_pats_in_trace_cs &&
		self.basis_pats_in_trace_igc>= other.basis_pats_in_trace_igc &&
		self.perc_pats_expansion_rate_cs >= other.perc_pats_expansion_rate_cs &&
		self.perc_pats_expansion_rate_igc >= other.perc_pats_expansion_rate_igc &&
		self.perc_comp_subsigs >= other.perc_comp_subsigs &&
		self.b_aggressive == other.b_aggressive
	}

	/// to get around the requirement on Clone trait which require Sized
	/// (which cause trouble why use dyn Capacity + Send + Sync in Rc),
	fn clone(&self) -> Arc<dyn Capacity + Send + Sync>{
		Arc::new(ComputeSigAdvCapacity{
			subsigs_cs: self.subsigs_cs,
			subsigs_igc: self.subsigs_igc,
			sigs: self.sigs,
			basis_pats_in_trace_cs: self.basis_pats_in_trace_cs,
			basis_pats_in_trace_igc: self.basis_pats_in_trace_igc,
			perc_pats_expansion_rate_cs: self.perc_pats_expansion_rate_cs,
			perc_pats_expansion_rate_igc: self.perc_pats_expansion_rate_igc,
			max_nibble_len: self.max_nibble_len,
			perc_comp_subsigs: self.perc_comp_subsigs,
			b_aggressive: self.b_aggressive,
			b_skip_igc: self.b_skip_igc,
		})
	}

	/// needed for downcasting for composite gadget mapper
	fn as_any(&self) -> &dyn Any { self }
}

impl <F: PrimeField + ColEle> NdAdvice for ComputeSigAdvAdvice<F>{
	fn as_any(&self) -> &dyn Any {self}
}

impl <F: PrimeField + ColEle> ComponentAdvice<F> for ComputeSigAdvAdvice<F>{
	fn get_container(&self)->std::sync::Arc<std::sync::Mutex<Container<F>>>{
		self.stmt_container.clone()
	}
}

impl <F: PrimeField + ColEle> ComputeSigAdvAdvice<F>{
	/// Given the StepQueue (result of bwd_prf) from the DischargeAdvGadget
	/// Generate the list of signatures that are discharged.
	pub fn new(
		acdfa_id_cs: u32,
		acdfa_id_igc: u32,
		inp_sigs: &Vec<F>,
		inp_subsigs_cs: &Vec<F>,
		inp_subsigs_igc: &Vec<F>,
		discharge_infos: &Vec<DischargeSigInfo>, //must match inp_sigs
					//extracting the dnf to the concat of inp_subsigs
		sq_res_cs: &std::sync::Arc<std::sync::Mutex<Container<F>>>, // the steps_queue from the DischargeAdv
		sq_res_igc: &std::sync::Arc<std::sync::Mutex<Container<F>>>, // the steps_queue from the DischargeAdv
		sq_inp_cs: &std::sync::Arc<std::sync::Mutex<Container<F>>>, // aggr seed tie source (neo: dan neo_core, legacy: sq_inp)
		sq_inp_igc: &std::sync::Arc<std::sync::Mutex<Container<F>>>,
		capacity: &ComputeSigAdvCapacity,
		subsig_store_info_cs: &SubsigStepStore,
		subsig_store_info_igc: &SubsigStepStore,
		subsig_extra_info_cs: &SubsigInfoStore,
		subsig_extra_info_igc: &SubsigInfoStore,
		v_sig_obj: &Vec<Arc<ClamavSig>>, //needs to cover all inp_sigs
		sig_to_id: &HashMap<String,usize>,
		_job_id: usize,
	) ->Result<Self, Error>{
		let stmt_container = Container::<F>::new("compute_sig_adv_stmt");
		let b_debug = B_DEBUG;

		//1. evaluate "atomic" subsigs based on sq_res 
		if inp_subsigs_cs.len()>capacity.subsigs_cs{
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs_cs"), inp_subsigs_cs.len())]));
		}
		assert!(inp_subsigs_cs.len()<=capacity.subsigs_cs, 
			"inp_subsigs_cs.len: {} should be <= capacity.subsigs: {}",
			inp_subsigs_cs.len(), capacity.subsigs_cs);
		if inp_subsigs_igc.len()>capacity.subsigs_igc{
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs_igc"), inp_subsigs_igc.len())]));
		}
		assert!(inp_subsigs_igc.len()<=capacity.subsigs_igc, 
			"inp_subsigs_igc.len: {} should be <= capacity.subsigs: {}",
			inp_subsigs_igc.len(), capacity.subsigs_igc);
		if inp_sigs.len()>capacity.sigs{
			return Err(Error::CapErr(vec![(format!("comp_sig::sigs"), 
				inp_sigs.len())]));
		}
		assert!(inp_sigs.len()<=capacity.sigs);
		let pad2 = vec![F::zero(); capacity.sigs-inp_sigs.len()];
		let dummy_di = DischargeSigInfo{
				sig_name: "none".to_string(),
				b_success: false,
				min_cost: 0,
				min_dnf_id: 0,
				subsig_ids: vec![0],
				subsig_igc: vec![false]
			}; 
		let discharge_info = [ &vec![dummy_di ;pad2.len()][..], 
			&discharge_infos[..]].concat();
		assert!(discharge_info.len()==capacity.sigs);


		//1.1 case sensitive (csa sits 2 gadgets after da_cs normally,
		//1 when the igc arm is skipped)
		let off_cs = if capacity.b_skip_igc {-1} else {-2};
		let pad_cs = vec![F::zero(); capacity.subsigs_cs-inp_subsigs_cs.len()];
		let inp_subsigs_cs = [&pad_cs[..], &inp_subsigs_cs[..]].concat();
		// E2 (T961): slot 0 must be the dummy 0 (assert in
		// gen_synthesis_subsig_combo); a full list has none. Real ids
		// are nonzero, so this fires iff len == cap (or cap == 0).
		if inp_subsigs_cs.first().map_or(true, |x| !x.is_zero()) {
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs_cs"),
				inp_subsigs_cs.len())]));
		}
		let inp_sigs = [&pad2[..], &inp_sigs[..]].concat();
		let (eval_res_combo_cs, raw_res_cs) =
			Self::gen_eval_subsig_by_sq_combo(false, off_cs, //case sensitive
			&inp_subsigs_cs, sq_res_cs, sq_inp_cs, &capacity,
			subsig_store_info_cs)?;
		#[cfg(test)] // T965 seam M4 (test only)
		let raw_res_cs = { let mut v = raw_res_cs; tests_compute_sig_adv::t965_seam(
			tests_compute_sig_adv::T965Stage::EvalCs,
			&eval_res_combo_cs, &mut v); v };
		stmt_container.lock().unwrap().add_container(eval_res_combo_cs);

		//1.2 ignore case (skipped when the igc universe is empty)
		let (inp_subsigs_igc, raw_res_igc) = if capacity.b_skip_igc {
			assert!(inp_subsigs_igc.is_empty(),
				"b_skip_igc with {} igc subsigs", inp_subsigs_igc.len());
			(vec![], vec![])
		} else {
			let pad_igc = vec![F::zero();
				capacity.subsigs_igc-inp_subsigs_igc.len()];
			let inp_subsigs_igc =
				[&pad_igc[..], &inp_subsigs_igc[..]].concat();
			let (eval_res_combo_igc, raw_res_igc) =
				Self::gen_eval_subsig_by_sq_combo(true, -1, //ignore case
				&inp_subsigs_igc, sq_res_igc, sq_inp_igc, &capacity,
				subsig_store_info_igc)?;
			#[cfg(test)] // T965 seam M4 (test only)
			let raw_res_igc = { let mut v = raw_res_igc; tests_compute_sig_adv::t965_seam(
				tests_compute_sig_adv::T965Stage::EvalIgc,
				&eval_res_combo_igc, &mut v); v };
			stmt_container.lock().unwrap()
				.add_container(eval_res_combo_igc);
			(inp_subsigs_igc, raw_res_igc)
		};

		//2. based on non-deterministic advice of eval order
		let (synthesis_res_combo, subsig_res) = 
			Self::gen_synthesis_subsig_combo(
			acdfa_id_cs, acdfa_id_igc,
			&inp_subsigs_cs, 
			&inp_subsigs_igc, 
			&raw_res_cs, &raw_res_igc,
			&capacity, 
			subsig_store_info_cs, 
			subsig_extra_info_cs, subsig_extra_info_igc)?;
		#[cfg(test)] // T965 seam M4 (test only)
		let subsig_res = { let mut v = subsig_res; tests_compute_sig_adv::t965_seam(
			tests_compute_sig_adv::T965Stage::Synth,
			&synthesis_res_combo, &mut v); v };
		stmt_container.lock().unwrap().add_container(synthesis_res_combo);

		//3. based on the sysntehsis resout of subsigs
		let inp_subsigs = vec![&inp_subsigs_cs[..], &inp_subsigs_igc[..]]
			.concat();
		//NOTE just keep it concated, no need to sort
		let sig_res_combo = Self::gen_discharge_sig_combo(
			&inp_sigs, 
			&inp_subsigs, 
			&subsig_res, 
			&capacity, 
			v_sig_obj,
			&discharge_info, 
			sig_to_id,
		)?;
		#[cfg(test)] // T965 seam M4 (test only)
		tests_compute_sig_adv::t965_seam(tests_compute_sig_adv::T965Stage::Sig,
			&sig_res_combo, &mut Vec::new());
		stmt_container.lock().unwrap().add_container(sig_res_combo);

		//3. allocates the discharged_sigs buffer
		Ok( Self{capacity: Clone::clone(capacity), stmt_container} )
	}

	/// generate the evaluation results for atomic subsigs using
	/// step queue. The basic idea is to examin the last step reached
	/// for a subsig. If it is the max step as defined (and there are
	/// valid locations), the result is Maybe, otherwise the result is
	/// False.
	/// Return (res_combo, raw_eval_result)
	/// -- see the paper definition or approx_eval_pm_ bounds_subsig in clamav.rs.
	/// Might throw CapErr: subsigs.
	fn gen_eval_subsig_by_sq_combo(
		b_igc: bool,
		offset_discharge: i32,
		inp_subsigs: &Vec<F>, //this is either one of inp_subsigs_cs or igc
		sq_res: &std::sync::Arc<std::sync::Mutex<Container<F>>>, //already sorted on subsig_step
		sq_inp: &std::sync::Arc<std::sync::Mutex<Container<F>>>, //aggr seed tie source (neo_core / legacy sq_inp)
		capacity: &ComputeSigAdvCapacity,
		subsig_store_info: &SubsigStepStore,
	)->Result<(std::sync::Arc<std::sync::Mutex<Container<F>>>,Vec<F>), Error>{
		//AGGRESSIVE: derive the verdict by MEMBERSHIP in the failed_subsigs
		//accumulator (sq_res is acc_out) instead of from the sq_res2 last-step.
		if capacity.b_aggressive{
			return Self::gen_eval_subsig_by_acc(b_igc, offset_discharge,
				inp_subsigs, sq_res, sq_inp, capacity, subsig_store_info);
		}
		//0. init data
		let b_debug = B_DEBUG;
		let (zero,one) = (F::zero(), F::one());
		let tname = if b_igc {"eval_res_combo_igc"} 
			else {"eval_res_combo_cs"};
		let res = Container::<F>::new(tname);
		// inp_subsigs is the CS vector when !b_igc (padded to subsigs_cs at the
		// call site) and the IGC vector when b_igc (padded to subsigs_igc), so
		// the cap MUST match the same branch -- the two were swapped, which only
		// surfaced once subsigs_cs and subsigs_igc diverged (e.g. the scale
		// sweep bumps subsigs_cs alone), tripping the exact-equality assert.
		let cap_subsigs = if b_igc {capacity.subsigs_igc} else
			{capacity.subsigs_cs};
		assert!(inp_subsigs.len()==cap_subsigs,
			"inp_subsigs.len {} != cap_subsigs {} (b_igc={})",
			inp_subsigs.len(), cap_subsigs, b_igc);
		let sname = if b_igc {"discharge_adv_stmt_igc"}
			else {"discharge_adv_stmt_cs"};
		// neo non-aggr: the discharge output is the carry q_c (added
		// directly under the stmt), not the legacy bwd_steps_queue.
		let use_neo = read_global_config()
			.clamav_cfg.b_use_discharge_neo;
		let sq_res_path = if use_neo {
			format!("{} q_c", sname)
		} else {
			format!("{} bwd_steps_queue sq_res2", sname)
		};
		let sq_res = sq_res.lock().unwrap().duplicate_as_external_adv(
			offset_discharge,
			Some(sq_res_path),
			Some("sq_res".to_string())); //so later we do not have to create copy
										 //in validate.

		//1. extract subsig, and its last step from sq_res
		let vec_subsig = sq_res.get_container("subsig").unwrap()
			.lock().unwrap().to_vec();
		let vec_step = sq_res.get_container("step").unwrap()
			.lock().unwrap().to_vec();
		let vec_encoded= sq_res.get_container("encoded").unwrap()
			.lock().unwrap().to_vec();
		let vec_sid_step= sq_res.get_container("si_step")
			.unwrap().lock().unwrap().to_vec();
		assert!(vec_subsig.len()==vec_step.len());
		assert!(inp_subsigs.len()==cap_subsigs);
	
		//the following loop are based on the assumption that
		//sq_res is already sorted on (subsig-step), and
		//its subsig is exactly the inp_subsigs
		let (n,n2) = (inp_subsigs.len(), vec_subsig.len());
		// Slots the walk below needs: it steps cur_idx (from n-2) down once
		// per run boundary in vec_subsig, so one slot per run plus the dummy
		// 0 entry. Reported when the walk runs out of slots (see cur_idx).
		let n_runs = 1 + (1..n2).filter(|&v|
			vec_subsig[v] != vec_subsig[v-1]).count();
		let mut vec_last_step= vec![zero;n];
		let mut inp_subsig_encoded = vec![zero;n]; //corresponds to inp_subsig 
		vec_last_step[n-1] = vec_step[n2-1];
		assert!(inp_subsigs[n-1]==vec_subsig[n2-1]);
		inp_subsig_encoded[n-1]=vec_encoded[n2-1];
		if !inp_subsigs.contains(&zero){
			// _cs/_igc, not {true,false}: apply_caperr_bumps detects the igc
			// arm by the "subsigs_igc" marker, so "subsigs_true" fell through
			// to the generic subsigs branch and bumped the CS field.
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs_{}",
				if b_igc {"igc"} else {"cs"}), inp_subsigs.len()+1)]));
		}
		assert!(inp_subsigs.contains(&zero), 
			"inp_subigs needs one dummy 0 entry");
		// n==1 leaves only the dummy 0 slot, so `n-2` below wraps to usize::MAX
		// and indexes out of bounds. Reachable once a tuner seeds subsigs from
		// a zero obligation demand; report it as a bumpable cap like the
		// out-of-slots case in the walk rather than panicking unparseably.
		if n < 2 {
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs_{}",
				if b_igc {"igc"} else {"cs"}), n_runs + 1)]));
		}
		let mut cur_idx = n-2;
		let mut v_idx = n2-1;
		for j in 1..n2{//from last to first
			v_idx = n2-j;
			if vec_subsig[v_idx]!=vec_subsig[v_idx-1]{
				// out of slots: cur_idx would wrap past 0 to usize::MAX and
				// index out of bounds below. Only reachable when it STARTS
				// at 0 (n==2) -- for n>=3 the cur_idx==0 break catches it --
				// but guard the decrement itself so the cap is bumpable
				// instead of panicking unparseably past determine_config.
				if cur_idx == 0 {
					return Err(Error::CapErr(vec![(
						format!("comp_sig::subsigs_{}",
							if b_igc {"igc"} else {"cs"}), n_runs + 1)]));
				}
				assert!(inp_subsigs[cur_idx]==vec_subsig[v_idx-1]);
				vec_last_step[cur_idx]=vec_step[v_idx-1];
				inp_subsig_encoded[cur_idx]=vec_encoded[v_idx-1];
				cur_idx -=1;
			}
			if cur_idx==0 {break;}
		}
		for j in 0..v_idx{//verify the rest are zero
			assert!(vec_subsig[j].is_zero() || vec_subsig[j]==inp_subsigs[cur_idx+1]);	
		}
		//now set the zero entries
		while cur_idx>0{
			assert!(inp_subsigs[cur_idx]==zero);
			inp_subsig_encoded[cur_idx]=vec_encoded[0];
			cur_idx-=1;
		}

		//2. extract the max_step for subsig
		let v_false = F::from(TriVal::False as u8);
		let v_maybe = F::from(TriVal::Maybe as u8);
		let mut vec_res = vec![v_false; n];
		let mut sid_last_step= vec![
				//for dummy subsig 0, last step is 0 (see discharge_adv)
				//built of vec_sid_step
				SubsigStepStore::gen_step_tbl_id(F::zero(),ID_ENCODED_LAST_STEP); n
		];
		for i in 0..n{
			if inp_subsigs[i]==zero{
				//vec_res[i] = F::from(TriVal::False as u8);
				vec_res[i] = F::zero();
			}else{
				let info = subsig_store_info.subsig_to_steps
					.get(&field_to_usize(&inp_subsigs[i])).expect(
					&format!("cannot find info for subsig: {}", inp_subsigs[i]));
				let max_step = F::from(info.vec_pm_bounds.len() as u64);
				assert!(max_step>=vec_last_step[i]);
				let b_last_step = max_step==vec_last_step[i];
				vec_res[i] = if b_last_step {v_maybe} else {v_false};
				let tag = if b_last_step {ID_ENCODED_LAST_STEP} else
					{ID_ENCODED_NORMAL_STEP};
				let sid = SubsigStepStore::gen_step_tbl_id(
					inp_subsig_encoded[i], tag);
	
				sid_last_step[i] = sid;
			}
		}

		//3. proof step1: assert that (encoded,subsig, last_step,sid_last_step) 
		// is the valid
		//from sq_res. only need one-direction lookup, since if there
		//are subsigs missed from sq_res, they won't show up in the
		//final evaluation result anyway (and cannot be discharged).
		//it's the loss of prover,and cannot affect soundness (but likley
		//raise false alarm). So it's ok to do 1-direction lookup.
		//We actually do tuple (inp_subsig_encoded, inp_subsig, last_step)
		//to futher bind inp_subsig with inp_subsig_encoded.
		if vec_subsig[0]!=zero{
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs"), 
				vec_subsig.len()+1)]));
		}
		assert!(vec_subsig[0]==zero, "need to have at least one dummy");
		let src= encode_cols_better( vec![&inp_subsig_encoded[..],
			&inp_subsigs[..], &vec_last_step[..], &sid_last_step[..]],
			vec![0,1,2,3]);
		let dst_sel = (0..n2).into_par_iter().map(|i|{
			if i==n2-1{one} else{
				if vec_subsig[i]==vec_subsig[i+1] {zero} else {one}
			}
		}).collect::<Vec<F>>();
		let dst_combined = encode_cols_better(vec![&vec_encoded[..],
			&vec_subsig[..], &vec_step[..], &vec_sid_step[..]], vec![0,1,2,3]);
		let dst = dst_combined.iter().zip(dst_sel.iter()).map(|(a,b)|
			*a * *b).collect::<Vec<F>>();
		let mtbl_last_step = gen_m_table(&src, &dst);
		let sid_m_tbl_last_step = vec![zero; mtbl_last_step.len()];

		//4. proof step2: assert that res is correct regarding that
		//sid_last_step == sid_max_step. This does not need any proof
		//generated. on the validator side, use encoded info to do the
		//verification.

		//5. add the columns (last_step, res)
		assert!(vec_res.len()==n);
		let frg = F::from(RANGE2);
		res.lock().unwrap().add_container(Arc::new(Mutex::new(sq_res)));
		res.lock().unwrap().add_col(Col::new(inp_subsigs.clone(), 
			"inp_subsig", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n], "sid_inp_subsig", 
			IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(inp_subsig_encoded, 
			"inp_subsig_encoded", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![zero;n], 
			"sid_inp_subsig_encoded", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(vec_last_step, "last_step", IDX_DATA));
		res.lock().unwrap().add_col(Col::new(sid_last_step, "sid_last_step", 
			IDX_SI_DATA)); //can't be const
		res.lock().unwrap().add_col(Col::new(vec_res.clone(), 
			"subsig_raw_eval", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n], 
			"sid_subsig_raw_eval", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(mtbl_last_step, "mtbl_last_step", 
			IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(sid_m_tbl_last_step,
			"sid_mtbl_last_step", IDX_SI_DATA)); //it's zero
		Ok( (res, vec_res) )
	}

	/// AGGRESSIVE-ONLY. Eval each subsig by MEMBERSHIP in the failed_subsigs
	/// accumulator (acc_out, passed as `acc_ct`): Maybe iff the subsig's
	/// LAST_STEP `encoded` key is in acc_out, else False. The key is
	/// re-derived via StepQueueItem::from_subsig_store_item so it matches
	/// the keys C5 puts into acc_out byte-for-byte. Emits the 4 encode
	/// sub-fields (range-checked via si=RANGE2) so validate can bind the
	/// key to inp_subsig. Returns (combo, vec_res) like the sq_res path.
	fn gen_eval_subsig_by_acc(
		b_igc: bool,
		offset_discharge: i32,
		inp_subsigs: &Vec<F>,
		acc_ct: &std::sync::Arc<std::sync::Mutex<Container<F>>>,
		sq_inp: &std::sync::Arc<std::sync::Mutex<Container<F>>>,
		capacity: &ComputeSigAdvCapacity,
		subsig_store_info: &SubsigStepStore,
	)->Result<(std::sync::Arc<std::sync::Mutex<Container<F>>>,Vec<F>), Error>{
		let zero = F::zero();
		let tname = if b_igc {"eval_res_combo_igc"} else {"eval_res_combo_cs"};
		let res = Container::<F>::new(tname);
		let sname = if b_igc {"discharge_adv_stmt_igc"}
			else {"discharge_adv_stmt_cs"};
		// CS-only aggressive mode allows subsigs_igc < subsigs_cs; when
		// symmetric this is identical. The non-aggr gen() is left as-is.
		let cap_subsigs = if b_igc {capacity.subsigs_igc}
			else {capacity.subsigs_cs};
		assert!(inp_subsigs.len()==cap_subsigs);
		let n = inp_subsigs.len();
		assert!(n >= 1, "by_acc: empty subsig list (cap {}, b_igc={})",
			cap_subsigs, b_igc);

		//1. external ref to acc_out (committed; no extra space)
		let acc_ext = acc_ct.lock().unwrap().duplicate_as_external_adv(
			offset_discharge,
			Some(format!("{} failed_acc_combo failed_acc", sname)),
			Some("acc_ref".to_string())); //distinct name (avoid collision
				//with the source container also named "failed_acc")
		let acc_set: Vec<F> = acc_ext.get_container("acc_encoded").unwrap()
			.lock().unwrap().to_vec();
		//keys are full-width encoded values; key the membership set by the
		//byte repr (field_to_usize only handles 32-bit values).
		let acc_lookup: HashSet<Vec<u8>> = acc_set.iter()
			.filter(|f| !f.is_zero())
			.map(|f| f.into_bigint().to_bytes_le()).collect();

		// 8_A: this fn is aggressive-only, so neo here means aggr-neo.
		// non-aggr-neo never reaches gen_by_acc.
		// M7 seed tie: pin inp_subsig to the seeded set. This replaces
		// the QUICK cert: a subsig with a False verdict must have been
		// seeded (else it is absent from the table and the logup fails).
		// Legacy (non-neo): ext-ref the forward seed sq_inp.encoded,
		// query encode(inp_subsig) (the seed's step-0 encoding).
		// T927 ST (aggr-neo): sq_inp is dan's neo_core. Ext-ref only
		// its "subsigs" (+ si) column: the K anchored seed slots
		// (dan assert_seed_anchors). Table = [0] ++ subsigs, plain ids
		// (the 0 absorbs the dummy-0 queries). Legacy keeps sq_inp.
		let b_st = read_global_config().clamav_cfg.b_use_discharge_neo;
		let (seed_ext, qry, tbl) = if b_st {
			let ext = Container::<F>::new("seed_ref");
			for c in ["subsigs", "si_subsigs"] {
				let col = sq_inp.lock().unwrap().get_container(c).unwrap();
				let d = col.lock().unwrap().duplicate_as_external(
					offset_discharge, Some(format!("{} neo_core {}",
					sname, c)));
				ext.lock().unwrap().add_container(Arc::new(Mutex::new(d)));
			}
			let mut tbl = vec![zero];
			tbl.extend(ext.lock().unwrap().get_container("subsigs")
				.unwrap().lock().unwrap().to_vec());
			(ext, inp_subsigs.clone(), tbl)
		} else {
			let ext = sq_inp.lock().unwrap().duplicate_as_external_adv(
				offset_discharge,
				Some(format!("{} fwd_steps_queue sq_inp", sname)),
				Some("seed_ref".to_string()));
			let tbl = ext.get_container("encoded").unwrap()
				.lock().unwrap().to_vec();
			let zc = vec![zero; n];
			(Arc::new(Mutex::new(ext)), encode_cols(&vec![
				inp_subsigs.clone(), zc.clone(), zc.clone(), zc.clone(),
				zc], &vec![0,1,2,3,4]), tbl)
		};
		let mtbl_seed = gen_m_table(&qry, &tbl);
		let nm2 = mtbl_seed.len();

		//2. per inp_subsig: LAST_STEP encoded key + its 4 encode sub-fields
		//   (step, pat, rg_start, rg_end) + the membership verdict.
		let v_false = F::from(TriVal::False as u8);
		let v_maybe = F::from(TriVal::Maybe as u8);
		let mut encoded_last = vec![zero; n];
		let (mut f_step, mut f_pat, mut f_rgs, mut f_rge) =
			(vec![zero;n], vec![zero;n], vec![zero;n], vec![zero;n]);
		let mut vec_res = vec![v_false; n];
		for i in 0..n{
			if inp_subsigs[i].is_zero(){ vec_res[i]=zero; continue; }
			let su = field_to_usize(&inp_subsigs[i]);
			let item = subsig_store_info.subsig_to_steps.get(&su)
				.expect(&format!("no store item for subsig {}", su));
			let num = item.vec_pm_bounds.len();
			//CU10 (M4): backward subsigs are discharged over the REVERSED,
			//keyword-first chain (CU2), so the accumulator stores the reversed
			//last-step key. Derive the membership key from the same reversed
			//chain here, else a matched backward subsig is not found in the
			//accumulator. Forward subsigs (flag-off) take the stored chain
			//verbatim -> byte-identical.
			let max_val:usize = (1<<read_global_config().range2_bit) - 1;
			let rev_item;
			let use_item = if item.is_backward {
				rev_item = SubsigStepStoreItem{ subsig_id: item.subsig_id,
					igc: item.igc, is_backward: item.is_backward,
					vec_pm_bounds: reverse_pm_bounds(
						&item.vec_pm_bounds, (0, max_val)) };
				&rev_item
			} else { item };
			let sqi = StepQueueItem::from_subsig_store_item(use_item, num,
				inp_subsigs[i], vec![]);
			encoded_last[i] = sqi.encoded;
			f_step[i] = sqi.step; f_pat[i] = sqi.pat;
			f_rgs[i] = sqi.rg_start; f_rge[i] = sqi.rg_end;
			vec_res[i] = if acc_lookup.contains(
				&sqi.encoded.into_bigint().to_bytes_le())
				{v_maybe} else {v_false};
		}
		//3. maybe_masked: the key iff Maybe (else 0); logup acc_out ⊆ this
		let maybe_masked: Vec<F> = (0..n).map(|i|
			if vec_res[i]==v_maybe {encoded_last[i]} else {zero}).collect();
		let mtbl = gen_m_table(&acc_set, &maybe_masked);


		//4. assemble combo. encoded key uses si=0 (large, not range-checked);
		//   inp_subsig + 4 sub-fields use si=RANGE2 (auto range-check <f1) so
		//   the key↔inp_subsig binding is canonical (validate enforces the sum).
		let frg = F::from(RANGE2);
		let nm = mtbl.len();
		res.lock().unwrap().add_container(Arc::new(Mutex::new(acc_ext)));
		res.lock().unwrap().add_col(Col::new(inp_subsigs.clone(),
			"inp_subsig", IDX_DATA));
		// T961 F1: inp is ranged by "inp_subsig_chain" (LOAD-BEARING,
		// see validate_eval_subsig_by_acc), not by its own si.
		res.lock().unwrap().add_col(Col::new_const(vec![zero;n],
			"sid_inp_subsig", IDX_SI_DATA));
		// chain d (n+1 cells, all RANGE2): d[0] = inp[0], d[n] = inp[n-1],
		// d[i] = inp[i] - inp[i-1] - [inp[i-1] != 0] in between. A const
		// si col uses only its 1st value in circuit: keep it uniform.
		let nz = |x: &F| if x.is_zero() {zero} else {F::one()};
		let chain: Vec<F> = (0..=n).map(|i| if i == 0 {inp_subsigs[0]}
			else if i == n {inp_subsigs[n-1]}
			else {inp_subsigs[i] - inp_subsigs[i-1] - nz(&inp_subsigs[i-1])})
			.collect();
		res.lock().unwrap().add_col(Col::new(chain, "inp_subsig_chain",
			IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n+1],
			"sid_inp_subsig_chain", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(encoded_last,
			"inp_subsig_encoded", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![zero;n],
			"sid_inp_subsig_encoded", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(f_step, "enc_step", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],
			"sid_enc_step", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(f_pat, "enc_pat", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],
			"sid_enc_pat", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(f_rgs, "enc_rgs", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],
			"sid_enc_rgs", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(f_rge, "enc_rge", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],
			"sid_enc_rge", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(vec_res.clone(),
			"subsig_raw_eval", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],
			"sid_subsig_raw_eval", IDX_SI_DATA));
		res.lock().unwrap().add_col(Col::new(mtbl, "mtbl_membership",
			IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![zero;nm],
			"sid_mtbl_membership", IDX_SI_DATA));
		// M7 seed tie: external-ref seed + the subset-of m-table.
		res.lock().unwrap().add_container(seed_ext);
		res.lock().unwrap().add_col(Col::new(mtbl_seed, "mtbl_seed",
			IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![zero;nm2],
			"sid_mtbl_seed", IDX_SI_DATA));
		Ok( (res, vec_res) )
	}

	/// Given the raw evaluation result for each subsig,
	/// return the synthesis result, based on subsig type.
	/// It evaluates all 3 possible outcomes: (1) regular subsig -
	///    which is the raw result, (2) counter constraint
	///    (3) result for component subsigs.
	/// then pick the final result from the three.
	/// the column "subsig_final_result" is the real evaluation result
	/// for a subsig.
	/// see accpets_approx_pm_bounds() in clamav.rs for the processing logic
	/// Return (ProofCombo, FinalEvalResult for the inp_subsigs padded)
	///
	/// Note that inp_subsigs_cs and inp_subsigs_igc are DISJOINT
	///   similarly, raw_results_cs and raw_result_igc are DISJOINT.
	/// Note that raw_result has two versions: (1) case sensitive (cs)
	/// and (2) IGC (ignore case). 
	///   inp_subsigs = union of inp_subsigs_cs + inp_subsigs_igc
	///   raw_result = union of raw_result_cs + raw_result_igc
	/// --- TO REMOVE BELOW ---
	///First, we have to pick up the
	/// value based on b_igc of each subsig and merge the raw_result_cs
	/// and raw_result_igc into one raw_result, and then the synthesis 
	/// can be done.
	/// --- TO REMOVE ABOVE
	/// Might throw CapErr: subsigs, perc_comp_subsigs
	fn gen_synthesis_subsig_combo(
		acdfa_id_cs: u32, 
		acdfa_id_igc: u32, 
		inp_subsigs_cs: &Vec<F>,
		inp_subsigs_igc: &Vec<F>,
		raw_result_cs: &Vec<F>, //one to one corresponding to inp_subsig, TriVal
		raw_result_igc: &Vec<F>, 
		capacity: &ComputeSigAdvCapacity,
		_subsig_store_info: &SubsigStepStore,
		subsig_store_extra_info_cs: &SubsigInfoStore,
		subsig_store_extra_info_igc: &SubsigInfoStore,
	)->Result<(std::sync::Arc<std::sync::Mutex<Container<F>>>,Vec<F>),Error>{
		//0. retrieve data 
		let b_debug = B_DEBUG;
		let n1_cs = inp_subsigs_cs.len(); //capacity num_subsigs
		let n1_igc = inp_subsigs_igc.len(); //capacity num_subsigs
		assert!(n1_cs==capacity.subsigs_cs);
		//skip mode: the igc set is empty, not capacity-padded
		assert!(n1_igc== if capacity.b_skip_igc {0}
			else {capacity.subsigs_igc});
		let (zero,one) = (F::zero(), F::one());
        let max_val:usize = (1<<read_global_config().range2_bit) - 1;
        let max = F::from(max_val as u64);
		let res = Container::<F>::new("synthesis_res_combo");
		let frg = F::from(RANGE2);

		//0.5 merge the inp_subsigs and raw_result.
		//NOTE that inp_subsigs is simply a concat of input_subsigs_cs and igc.
		// Disjointness (one slot per subsig overall) is enforced by the
		// NH3 arm TYPE tag + the per-list F1 chain (T961).
		if b_debug{//inp_subsigs_cs and inp_subsigs_igc are disjoint
			//for non-zero values
			let vec1= inp_subsigs_cs.iter().filter(|x| !x.is_zero())
				.map(|&x| x).collect::<Vec<F>>();
			let vec2= inp_subsigs_igc.iter().filter(|x| !x.is_zero())
				.map(|&x| x).collect::<Vec<F>>();
			let set1 = vec1.iter().map(|&x| x).collect::<HashSet<F>>();
			let set2 = vec2.iter().map(|&x| x).collect::<HashSet<F>>();
			assert!(vec1.len()==set1.len());
			assert!(vec2.len()==set2.len());
			assert!(set1.is_disjoint(&set2));

		}
		let inp_subsigs = vec![&inp_subsigs_cs[..], &inp_subsigs_igc[..]]
			.concat();
		let raw_result = vec![&raw_result_cs[..], &raw_result_igc[..]]
			.concat();
		let n1 = n1_cs + n1_igc;
		assert!(inp_subsigs.len()==n1 && raw_result.len()==n1);


		//1. prepare the result of general_regex
		let gen_regex_res = raw_result;
		assert!(gen_regex_res.len()==inp_subsigs.len());
		let map_gen_regex_res = inp_subsigs.iter()
			.zip(gen_regex_res.iter()).map(|(sig,res)|{
			let u_sig = field_to_usize(sig);
			(u_sig, *res)
		}).collect::<HashMap<usize, F>>();

		//2. prepare the result for counter_constraint 
		// the structure for each subsig is
		// (num, op, counter_res) where counter_res is defined using
		// logic: case op
		// NONE => Maybe (this is actually don't care value)
		// LT => !raw_res
		// EQ => if num!=0 {res} else {!res}
		// GT => res
		// We need to tab num and op appropriate usingly ID_COMP_OP
		//  and ID_COMP_NUM so that we can check them in lookup table
		let mut vec_type = vec![zero; n1]; 
		let mut vec_op = vec![zero; n1];
		let mut vec_num = vec![zero; n1];
		let mut vec_counter_res = vec![zero; n1]; //result for counter constraint 
		let mut vec_sid_op = vec![zero; n1];
		let mut vec_sid_num = vec![zero; n1];
		let vec_sid_counter_res = vec![zero; n1]; //no need to check 
												  //as res is generated in circ
		let mut vec_sid_type = vec![zero; n1];
		//we use simple for loop here as subsig num is small
		for i in 0..n1{
			let subsig = inp_subsigs[i];
			let f_subsig = field_to_usize(&subsig);
			let (op, num, subsig_type, acdfa_id) = if subsig.is_zero(){
				//NOTE: subsig 0 is treated as context sensitive
				//Maybe value
				(CompOp::NONE as u8, 0, 0, acdfa_id_cs)
			}else{
				//let b_igc = v_igc[i].is_one();
				let b_igc = i>=n1_cs; //first segment are all case sensitive.
				let subsig_store_extra_info = 
					if b_igc {subsig_store_extra_info_igc}
					else {subsig_store_extra_info_cs};
				let info = subsig_store_extra_info
					.subsig_to_rec.get(&field_to_usize(&subsig))
					.expect(&format!("cannot find step info for: {}", subsig));
				let acdfa_id = if b_igc {acdfa_id_igc} else {acdfa_id_cs};
				(info.comp_op, info.comp_num, info.subsig_type, acdfa_id)
			};
			let c_op = CompOp::from(op);
			//for input_subsig 0, dummy value for raw_res is 0
			//treat it like Maybe
			let raw_res = if gen_regex_res[i].is_zero() {TriVal::Maybe}
				else {TriVal::from(field_to_usize(&gen_regex_res[i]) as u8)};
			let count_res = match c_op{
				CompOp::NONE => raw_res,
				CompOp::LT => !raw_res,
				CompOp::EQ => if num!=0 {raw_res} else {!raw_res},
				CompOp::GT => raw_res,
			};
			let sid_op: F = SubsigInfoStore::gen_info_tbl_id(acdfa_id, 
				f_subsig, ID_COMP_OP);  
			let sid_num: F = SubsigInfoStore::gen_info_tbl_id(acdfa_id, 
				f_subsig, ID_COMP_NUM);  
			vec_op[i] = F::from(c_op as u8);
			vec_num[i] = F::from(num as u32);
			vec_counter_res[i] = F::from(count_res as u8);
			vec_sid_op[i] = sid_op;
			vec_sid_num[i] = sid_num;
			vec_type[i] = F::from(subsig_type as u8);
			//NH3 (T961): TYPE tag by arm (position), pads included
			let ty = if i>=n1_cs {ID_SUBSIG_TYPE_IGC} else {ID_SUBSIG_TYPE};
			vec_sid_type[i] = SubsigInfoStore::gen_info_tbl_id(acdfa_id,
				f_subsig, ty);
		}

		//3. prepare the result for the subsig_count_constraint
		// see accepts_approx_pm_bounds() handling of SubsigCountConstraint
		// collect the res of true, maybe, false on subcomponents
		// res = Ture if cnt_tru>min_required, 
		// False if cnt_true+cnt_maybe<min_required
		//
		// Idea: since the vec_components is not fixed, construct the
		// following tables:
		// (1) ssc_prf_tbl of the following structure. It COVERS ONLY
		//   those subsigs which has the SubsigCounterConstraint tag
		//   (subsig, comp_subsig_encoded, comp_subsig,
		//			raw_res, cnt_true, cnt_false, ssc_res)
		//   Here each subsig has at least 1 entry of comp_subsig_encoded
		//   the last is the MAX entry which ensures the "full retrieval"
		//   of its comp_subsig from database
		// We could have another table for last row for each subsig
		// to compute ssc_res, but given that the table is already
		// very small, we'll skip that second table and wasite a bit constraints
		// here, because  REAL DATA shows that: 
		// max_ratio is the ratio of those components being a part of another 
		// SubsigCountConstraint.
		// max_subsigs (for discharging a file):  1026, max_ratio 16.666668
		// avg_subsigs:  401.2398676592225 avg_ratio 7.11235321401159
		//
		// (2) ssc_res table which has the following structure, skip the
		// subsig column (as it's already there in combo)
		//  (subsig, ssc_type, ssc_res)
		//  the res is set to don't care if it's type is not SubsigCountConstraint
		// otherwise, we lookup the ssc_es in the ssc_prf_tbl

		// 3.1 construct the ssc_prf_tbl (for SubsigCounterConstraint ONLY!) 
		let factor = F::from(1u32 << read_global_config().range2_bit);
        let max_val:usize = (1<<read_global_config().range2_bit) - 1;
        let _max = F::from(max_val as u64);

		let mut scc_prf_subsig = vec![]; //scc_prf stands for subsig_count_constraint
		let mut scc_prf_comp_subsig_encode = vec![];  //encoded version with id 
		let mut scc_prf_comp_subsig = vec![];  //encoded version with id 
		let mut scc_prf_min_req = vec![];
		let mut scc_prf_raw = vec![]; //raw eval result for comp_subsig
		let mut scc_prf_cnt_true = vec![]; //current count for subsig
		let mut scc_prf_cnt_maybe = vec![]; //current count for subsig
		let mut scc_prf_row_res = vec![]; //current res at each row (take the one at max)
		let mut scc_prf_abs_diff1 = vec![]; //absolute value of cnt_true-min_req
		let mut scc_prf_abs_diff2 = vec![]; //absolute value of 
					//min_req - (cnt_true + cnt_maybe) - 1
				

		let mut sid_scc_prf_subsig = vec![]; 
		let mut sid_scc_prf_comp_subsig_encode = vec![];  
		let mut sid_scc_prf_comp_subsig = vec![];  
		let mut sid_scc_prf_min_req = vec![];
		let mut sid_scc_prf_raw = vec![]; 
		let mut sid_scc_prf_cnt_true = vec![]; 
		let mut sid_scc_prf_cnt_maybe = vec![]; 
		let mut sid_scc_prf_row_res = vec![]; 
		let mut sid_scc_prf_abs_diff1 = vec![];
		let mut sid_scc_prf_abs_diff2 = vec![];

		let mut vec_scc_res = vec![zero;n1]; //will be updated 
		let vec_sid_scc_res = vec![zero;n1]; //don't care because
									//vec_scc_res is computed.

		for i in 0..n1{
			//3.1.1 retrieve extra info
			let subsig = inp_subsigs[i];
			if subsig.is_zero(){
				vec_scc_res[i] = F::from(TriVal::Maybe as u8);
				continue;
			}
			let igc = i>=n1_cs;
			let acdfa_id = if igc {acdfa_id_igc} else {acdfa_id_cs};
			let subsig_store_extra_info = 
				if igc {subsig_store_extra_info_igc}
				else {subsig_store_extra_info_cs};
			let extra_info = subsig_store_extra_info
					.subsig_to_rec.get(&field_to_usize(&subsig))
					.expect(&format!("Can't find info for subsig: {}", subsig));
			if extra_info.subsig_type
				!=SubSigType::SubsigCountConstraint as u8{continue;}

			//3.1.2 insert entries
			let mut vec_comps = extra_info.component_subsigs.clone();
			vec_comps.push(max_val as usize);
			let min_req = extra_info.min_required;
			let mut cnt_true =0;
			let mut cnt_maybe = 0;
			for j in 0..vec_comps.len(){
				scc_prf_subsig.push(subsig);
				sid_scc_prf_subsig.push(zero); //don't care as it will be looked up

				let f1 = F::from((j+1) as u32); //starts from 1
                let f2 = F::from(vec_comps[j] as u64);
                let encoded = f1 + f2*factor;
				scc_prf_comp_subsig_encode.push(encoded);
				let tbl_id = SubsigInfoStore::gen_info_tbl_id::<F>(acdfa_id, 
					field_to_usize(&subsig), ID_COMP_SUBSIG); //comp_subsig BELONGS 
															 //to vec_comp of subsig
				sid_scc_prf_comp_subsig_encode.push(tbl_id);

				scc_prf_comp_subsig.push(f2);
				sid_scc_prf_comp_subsig.push(frg);

				scc_prf_min_req.push(F::from(min_req as u64));
				let tbl_id = SubsigInfoStore::gen_info_tbl_id::<F>(acdfa_id, 
					field_to_usize(&subsig), ID_MIN_REQUIRED); 
				sid_scc_prf_min_req.push(tbl_id); 
			
				let raw_res = if j<vec_comps.len()-1{
					*map_gen_regex_res.get(&vec_comps[j]).unwrap()
				}else{//for max: it's 0 - don't care
					F::zero()
				};
				// if dummy value set tri_raw_res as Maybe (don't care)
				// but here we do need its in-table value to be 0
				// so that later when we do lookup, we can save some
				// boolean cond var cost. because set selector to 0 (in mul)
				// make things easier. note for max it will not impact
				// cnt_true and cnt_maybe.
				let tri_raw_res = if raw_res.is_zero() {TriVal::False}
					else {TriVal::from(field_to_usize(&raw_res) as u8)};

				if tri_raw_res==TriVal::True{cnt_true+=1}
				else if tri_raw_res==TriVal::Maybe{cnt_maybe+=1};
				//do nothing for false as our logic does not need it

				//this corresonds to the logic in data_processor/src/clama.rs
				//accepts_approx_pm_bounds()
				let res = if cnt_true>=min_req{
					TriVal::True //for sure
				} else if cnt_true + cnt_maybe < min_req{
					TriVal::False //for sure
				} else {
					TriVal::Maybe //not for sure
				};
				let res = if j<vec_comps.len()-1{F::from(res as u8)} else {
					//copy from last
					scc_prf_row_res[scc_prf_row_res.len()-1]
				};

				let abs_diff1 = if cnt_true >= min_req {cnt_true - min_req}
					else {min_req - cnt_true};
				let abs_diff2 = if cnt_true + cnt_maybe < min_req {
					min_req - (cnt_true + cnt_maybe + 1)
				}else { cnt_true + cnt_maybe + 1 - min_req};
					

				scc_prf_raw.push(raw_res);
				sid_scc_prf_raw.push(zero); //don't care as it will be looked up
				scc_prf_cnt_true.push(F::from(cnt_true as u64));
				sid_scc_prf_cnt_true.push(zero); //don't care as it is computed
				scc_prf_cnt_maybe.push(F::from(cnt_maybe as u64));
				sid_scc_prf_cnt_maybe.push(zero); //don't care as it is computed
				scc_prf_row_res.push(res);
				sid_scc_prf_row_res.push(zero); //don't care as it is computed

				scc_prf_abs_diff1.push(F::from(abs_diff1 as u64));
				sid_scc_prf_abs_diff1.push(frg);
				scc_prf_abs_diff2.push(F::from(abs_diff2 as u64));
				sid_scc_prf_abs_diff2.push(frg);
				
				vec_scc_res[i] = res; //only the last row is valid
			}
		}

		let n2 = capacity.get_scc_prf_size();
		if scc_prf_subsig.len()+1>n2{
			let new_val = (scc_prf_subsig.len()+1)*100/(capacity.subsigs_cs + capacity.subsigs_igc) + 1;
			return Err(Error::CapErr(vec![(format!("comp_sig::perc_comp_subsigs"), new_val)]));

		}
		assert!(scc_prf_subsig.len()<=n2-1, "Adjust perc_comp_subsig in Config! Needed scc_prf len: {} < current_tuples: {}", n2, scc_prf_subsig.len());
		let pad = vec![F::zero(); n2-scc_prf_subsig.len()];
		let pad2 = vec![frg; n2-scc_prf_subsig.len()];
		//let igc = v_igc[0].is_one();
		let igc = false; //by default first entry is CS.
		let acdfa_id = if igc {acdfa_id_igc} else {acdfa_id_cs};
		//TODO: double check if this value is gauranteed in
		//the clam_db.rs to genreate dummy entry for subsig_id = 0
		let pad_comp_subsig_encode = vec![
			SubsigInfoStore::gen_info_tbl_id(acdfa_id,0,ID_COMP_SUBSIG)
			;n2-scc_prf_subsig.len()
		];
		let pad_min_req = vec![
			SubsigInfoStore::gen_info_tbl_id::<F>(acdfa_id, 
					0, ID_MIN_REQUIRED)
			;n2-scc_prf_subsig.len()
		];

		scc_prf_subsig = [&pad[..], &scc_prf_subsig[..]].concat(); 
		scc_prf_comp_subsig_encode = [&pad[..], &scc_prf_comp_subsig_encode[..]].concat(); 
		scc_prf_comp_subsig = [&pad[..], &scc_prf_comp_subsig[..]].concat();
		scc_prf_min_req = [&pad[..], &scc_prf_min_req[..]].concat();
		scc_prf_raw = [&pad[..], &scc_prf_raw[..]].concat(); //it's padding value will be 1
		scc_prf_cnt_true = [&pad[..], &scc_prf_cnt_true[..]].concat();
		scc_prf_cnt_maybe = [&pad[..], &scc_prf_cnt_maybe[..]].concat();
		scc_prf_row_res = [&pad[..], &scc_prf_row_res[..]].concat();
		scc_prf_abs_diff1 = [&pad[..], &scc_prf_abs_diff1[..]].concat();
		scc_prf_abs_diff2 = [&pad[..], &scc_prf_abs_diff2[..]].concat();

		// -- sids
		sid_scc_prf_subsig = [&pad[..], &sid_scc_prf_subsig[..]].concat(); 
			//const 0
		sid_scc_prf_comp_subsig_encode = [&pad_comp_subsig_encode[..], &sid_scc_prf_comp_subsig_encode[..]].concat(); //NON const
		sid_scc_prf_comp_subsig = [&pad2[..], &sid_scc_prf_comp_subsig[..]].concat(); //const

		sid_scc_prf_min_req = [&pad_min_req[..], &sid_scc_prf_min_req[..]].concat();
			//non const
		sid_scc_prf_raw = [&pad[..], &sid_scc_prf_raw[..]].concat(); //const 0
		sid_scc_prf_cnt_true = [&pad[..], &sid_scc_prf_cnt_true[..]].concat();
			//const 0
		sid_scc_prf_cnt_maybe = [&pad[..], &sid_scc_prf_cnt_maybe[..]].concat();
			//const 0
		sid_scc_prf_row_res = [&pad[..], &sid_scc_prf_row_res[..]].concat();
			//const 0
		sid_scc_prf_abs_diff1= [&pad2[..], &sid_scc_prf_abs_diff1[..]].concat();
			//const rg2
		sid_scc_prf_abs_diff2= [&pad2[..], &sid_scc_prf_abs_diff2[..]].concat();
			//const rg2
		assert!(vec_scc_res.len()==n1);
		assert!(vec_sid_scc_res.len()==n1);

		let col2d = [
			&scc_prf_subsig, &scc_prf_comp_subsig_encode, &scc_prf_comp_subsig,
			&scc_prf_min_req, &scc_prf_raw, &scc_prf_cnt_true, 
			&scc_prf_cnt_maybe, &scc_prf_row_res,
			&scc_prf_abs_diff1, &scc_prf_abs_diff2];
		let sid_col2d = [ 
			&sid_scc_prf_subsig, &sid_scc_prf_comp_subsig_encode, &sid_scc_prf_comp_subsig,
			&sid_scc_prf_min_req, &sid_scc_prf_raw, &sid_scc_prf_cnt_true,
			&sid_scc_prf_cnt_maybe, &sid_scc_prf_row_res,
			&sid_scc_prf_abs_diff1, &sid_scc_prf_abs_diff2
		];
		let bconst_sid_col2d = [
			true, false, true, false, true,
			true, true, true, true, true
		];
		assert!(bconst_sid_col2d.len()==sid_col2d.len());
		for c in col2d {assert!(c.len()==n2);}
		for c in sid_col2d {assert!(c.len()==n2);}

		//3.2 lookup (comp_subsig, raw_res) in the gen_regex_res
		// to prove the validity of raw_res for the comp_subsig
		// ignore the max entries
		let src_s_r = encode_cols_better(
			vec![&scc_prf_comp_subsig[..],&scc_prf_raw[..]],
			vec![0,1]
		);
		let src_sel = scc_prf_comp_subsig.iter().map(|s|
			if *s==max {zero} else {one}
		).collect::<Vec<F>>();
		let src_s_r = src_s_r.iter().zip(src_sel.iter()).map(|(a,b)|
			*a * *b).collect::<Vec<F>>();
		assert!(inp_subsigs[0].is_zero(), "we need one dummy subsig entry. Increase config.subsigs"); //so that we can save the selector
		let dest_s_r = encode_cols_better(
			vec![&inp_subsigs[..], &gen_regex_res[..]],
			vec![0,1]
		);
		let mtbl_comp_score = gen_m_table(&src_s_r, &dest_s_r);

		//3.3 and 3.4 which builds the log up and verify abs_diff
		//no need to build any additional (their SID cols already build
		//earlier

		//3.5 build vec_scc_res and perform logup
		//vec_scc_res has the same length of inp_subsigs
		//if its type is the SubsigCounterConstraint, then its value
		//is available in scc_prf_row_res (last row with comp_subsig=max).
		//otherwise we set its value to be don't care (Maybe), because
		//it will not be retrieved anyway.
		//and generate the corresponding logsups (based on vec_type)
		let var_scc = F::from(SubSigType::SubsigCountConstraint as u8); // 2
		let src_sel = vec_type.iter().map(|t|
			if *t==var_scc {one} else {zero}
		).collect::<Vec<F>>();

		assert!(vec_scc_res.len()==n1 && src_sel.len()==n1);
		let src = encode_cols_better(
			vec![&inp_subsigs[..], &vec_scc_res[..]],
			vec![0,1]
		);
		let src = src.iter().zip(src_sel.iter()).map(|(a,b)|
			*a * *b).collect::<Vec<F>>();

		let dst = encode_cols_better(
			vec![&scc_prf_subsig[..], &scc_prf_row_res[..]],
			vec![0,1]
		);
		let dst_sel = scc_prf_comp_subsig.iter().map(|c| 
			if *c==max {one} else {zero}
		).collect::<Vec<F>>();
		let dst = dst.iter().zip(dst_sel.iter()).map(|(a,b)|
			*a * *b).collect::<Vec<F>>();
		let mtbl_find_scc_res = gen_m_table(&src, &dst);

		//4. build the final table. idea is simple: we
		// use conditional selection to determine based on type
		let var_regular = F::from(SubSigType::GeneralRegex as u8); // 0
		let is_scc= src_sel; //saving cost
		let is_reg = vec_type.iter().map(|t|
			if *t==var_regular {one} else {zero}
		).collect::<Vec<F>>();
		let mut vec_subsig_final_res = vec![zero; n1];
		assert!(vec_scc_res.len()==n1);
		assert!(gen_regex_res.len()==n1);
		assert!(vec_counter_res.len()==n1);
		for i in 0..n1{//since it's small about 1k entries, just single thread
			vec_subsig_final_res[i] = if is_scc[i].is_one() {vec_scc_res[i]}
			else{
				if is_reg[i].is_one() {gen_regex_res[i]} 
				else {vec_counter_res[i]}
			}
		}
		let vec_sid_subsig_final_res = vec![zero; n1];//no need to check

		//5. construct container
		//5.1 the counter constraint part
		res.lock().unwrap().add_col(Col::new(vec_op, "vec_op", IDX_DATA)); 
		res.lock().unwrap().add_col(Col::new(vec_sid_op, 
			"sid_op", IDX_SI_DATA)); //not constnat
		res.lock().unwrap().add_col(Col::new(vec_num, "vec_num", IDX_DATA));
		res.lock().unwrap().add_col(Col::new(vec_sid_num, 
			"sid_num", IDX_SI_DATA)); //not constant
		res.lock().unwrap().add_col(Col::new(vec_counter_res, 
			"vec_counter_res", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec_sid_counter_res, 
			"sid_counter_res", IDX_SI_DATA)); //const 0
		res.lock().unwrap().add_col(Col::new(vec_type, "vec_type", IDX_DATA));
		res.lock().unwrap().add_col(Col::new(vec_sid_type, "vec_sid_type", 
			IDX_SI_DATA)); //non_const

		//5.2 the subsig counter constraint part
		let names = vec![
				"scc_prf_subsig",
				"scc_prf_comp_subsig_encode",
				"scc_prf_comp_subsig",
				"scc_prf_min_req",
				"scc_prf_raw",
				"scc_prf_cnt_true",
				"scc_prf_cnt_maybe",
				"scc_prf_row_res",
				"scc_prf_abs_diff1",
				"scc_prf_abs_diff2",
		];
		for i in 0..col2d.len(){
			res.lock().unwrap().add_col(Col::new(col2d[i].clone(), names[i], IDX_DATA));
			if bconst_sid_col2d[i]{ //only 2 are not constants
				res.lock().unwrap().add_col(Col::new_const(sid_col2d[i].clone(), 
					&format!("sid_{}",names[i]), IDX_SI_DATA));
			}else{
				res.lock().unwrap().add_col(Col::new(sid_col2d[i].clone(), 
					&format!("sid_{}",names[i]), IDX_SI_DATA));
			}
		}
		assert!(mtbl_comp_score.len()==n1);
		res.lock().unwrap().add_col(Col::new(mtbl_comp_score, 
			"mtbl_comp_score", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg; n1], 
			"sid_mtbl_comp_score", IDX_SI_DATA));

		assert!(mtbl_find_scc_res.len()==n2);
		res.lock().unwrap().add_col(Col::new(mtbl_find_scc_res, 
			"mtbl_find_scc_res", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg; n2], 
			"sid_mtbl_find_scc_res", IDX_SI_DATA));

		assert!(vec_scc_res.len()==vec_sid_scc_res.len());
		res.lock().unwrap().add_col(Col::new(vec_scc_res, 
			"vec_scc_res", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec_sid_scc_res, 
			"vec_sid_scc_res", IDX_SI_DATA)); //const zero

		//5.3 add the final result
		res.lock().unwrap().add_col(Col::new(vec_subsig_final_res.clone(),
			"vec_subsig_final_res", IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec_sid_subsig_final_res,
			"vec_sid_subsig_final_res", IDX_SI_DATA)); //zero


		Ok( (res, vec_subsig_final_res) )
	}

	/// Given the final result of subsig,
	/// use the EvalDNF information to discharge sig.
	/// Basic idea: each sig has a collection of EvalDNF (see type_def.rs)
	/// E.g., (1|2) & (3|4)
	/// It has two DNFs: (1|2) and (3|4)
	/// the Word Discharge Info has already pointed which one has
	/// lower cst to discharge, e.g., let it be (1|2).
	/// the combo needs to show that both subsigs 1 and 2 are 
	/// discharged (as False).
	/// 
	/// Proof Structure (table)
	/// sig - eval_dnf_id - step - count - subsig - res
	/// where the (subsig,res) is from the gen_synsis_subsig_combo.
	/// HERE: all sigs need to be discharged (they will be
	///   the list of sigs to be reported as "discharged").
	///
	/// might throw CapErr: subsigs, sigs
	fn gen_discharge_sig_combo(
		inp_sigs: &Vec<F>,
		inp_subsigs: &Vec<F>,
		subsig_result: &Vec<F>,
		capacity: &ComputeSigAdvCapacity,
		v_sigs: &Vec<Arc<ClamavSig>>, //required to COVER inp_sigs
		discharge_infos: &Vec<DischargeSigInfo>, //must match inp_sigs
					//extracting the dnf to the concat of inp_subsigs
		sig_to_id: &HashMap<String,usize>,
	)->Result<std::sync::Arc<std::sync::Mutex<Container<F>>>,Error>{
		let b_debug = B_DEBUG;
		let zero = F::zero();
		let frg = F::from(RANGE2);
		let res = Container::<F>::new("sig_res_combo");
		//skip mode: the igc arm contributes no subsig slots
		let n = capacity.subsigs_cs +
			if capacity.b_skip_igc {0} else {capacity.subsigs_igc};
		assert!(inp_subsigs.len()==n);
		assert!(subsig_result.len()==n);
		assert!(inp_sigs.len()==capacity.sigs);

		//1. from the discharge info, build the proof table
		// sig - eval_dnf_id - step - count - subsig (expect res to be
		// TriVal::False)
		// Special note: the subsig/res in this talbe is DIFFERENT
		// from the subsig/res in the gen_synthesis_subsig_res (because
		// here, we do NOT include the sub-components of a subsig (thus
		// resulting a shorter list of subsigs and with different structure)
		// we have to run a LOOKUP to retrieve the result values from
		// the previous combo in step 2.
		// NOTE: we pad the size to #subsigs because in real data
		// vast majority are regular_regex 
		// (not Counterh of SubsigCounterConstraint)
		if capacity.sigs<discharge_infos.len(){
			return Err(Error::CapErr(vec![(format!("comp_sig::sigs"), discharge_infos.len())]));
		}
		let pad_len = capacity.sigs - discharge_infos.len();
		let dummy_di = DischargeSigInfo{
				sig_name: "none".to_string(),
				b_success: false,
				min_cost: 0,
				min_dnf_id: 0,
				subsig_ids: vec![0],
				subsig_igc: vec![false]
			}; 
		let discharge_infos = [ 
			&vec![dummy_di ;pad_len][..], 
			&discharge_infos[..]
		].concat();
		assert!(discharge_infos.len()==inp_sigs.len());
		for i in 0..discharge_infos.len() {
			let name = &discharge_infos[i].sig_name;
			let sig_id = if name =="none" {zero} else {
				F::from(*sig_to_id.get(name)
					.expect(&format!("cannot find sig: {}", name)) as u64)
			};
			assert!(sig_id == inp_sigs[i]);
		}
		let info_ts = discharge_infos.par_iter().map(|info|{
			let (sig_id, vec_ssid) = if info.sig_name=="none" {//dummy case 
				//don't genreate [1] instead generate 0
				(zero, vec![])
			}else{
				let sig_objs = v_sigs.iter().filter(|s| s.name==info.sig_name)
					.map(|s| s.clone())//low cost of Arc clone
					.collect::<Vec<Arc<ClamavSig>>>();
				assert!(sig_objs.len()==1, "cannot find or duplicate entries for {}", info.sig_name);
				let sig_obj = &sig_objs[0];
				let sig_id = sig_to_id.get(&info.sig_name)
					.expect(&format!("cannot find sig: {}", info.sig_name));
				let sig_id = F::from(*sig_id as u64);
				let dnf_id = info.min_dnf_id;
				let vssid = sig_obj.eval_dnf.vec_disjunc[dnf_id].iter().map(
					|x| F::from((*x+1) as u64)).collect::<Vec<F>>();
				if b_debug{
					let vec_bad_subsig_id = vec![
						F::from(35360770 as u64),
					];
					for ssid in &vssid{
						let real_subsig_id = field_to_usize(ssid) - 1;
						let my_subsig_id = 
							F::from(
								HexACDFA::gen_subsig_id_worker(
								field_to_usize(&sig_id), 
								real_subsig_id+1) as u128);
						let b_match = vec_bad_subsig_id.iter().any(|x|
							*x == my_subsig_id);
					}
				}
				(sig_id, vssid)
			};
			let eval_dnf_id = F::from(info.min_dnf_id as u64);
			let eval_count = F::from(vec_ssid.len() as u64);
			vec_ssid.iter().enumerate().map(|(i,ssid)|
				(eval_dnf_id, F::from(i as u64), eval_count, *ssid, sig_id)
			).collect::<Vec<(F,F,F,F,F)>>()
		}).flatten().collect::<Vec<(F,F,F,F,F)>>();
		if n<info_ts.len(){
			return Err(Error::CapErr(vec![(format!("comp_sig::subsigs"), info_ts.len())]));
		}
		let pad = vec![(zero,zero,zero,zero,zero); n-info_ts.len()];
		let info_ts = [&pad[..], &info_ts[..]].concat();
		assert!(info_ts.len()==n);
		let v_dnf_id = info_ts.iter().map(|t| t.0).collect::<Vec<F>>();
		let v_dnf_step = info_ts.iter().map(|t| t.1).collect::<Vec<F>>();
		let v_dnf_count = info_ts.iter().map(|t| t.2).collect::<Vec<F>>();
		let v_real_subsigs = info_ts.iter().map(|t| t.3).collect::<Vec<F>>();
		let v_sigs = info_ts.iter().map(|t| t.4).collect::<Vec<F>>();

		let info_id:u32 = 0x98882405; 
		let f1 = F::from(info_id);
		let factor = F::from(0x100000000 as u64); //32-bit 
		let v_sid_dnf_id = vec![frg; n];
		let v_sid_dnf_step = vec![frg; n];
		let v_sid_dnf_count= (0..n).collect::<Vec<usize>>().into_iter().map(|i|{
			let dnf_id = v_dnf_id[i];
			let sig_id = v_sigs[i];
			let tbl_id = f1*factor*factor*factor + sig_id * factor * factor
				+ dnf_id * factor;

			tbl_id
		}).collect::<Vec<F>>();

		let info_id:u32 = 0x99992405; 
		let f1 = F::from(info_id);
		let v_sid_real_subsigs= (0..n).collect::<Vec<usize>>()
			.into_iter().map(|i|{
			let dnf_id = v_dnf_id[i];
			let sig_id = v_sigs[i];
			let tbl_id = f1*factor*factor*factor + sig_id * factor * factor
				+ dnf_id * factor + v_dnf_step[i];

			tbl_id
		}).collect::<Vec<F>>();
		let v_sid_sigs = vec![frg; n];

		//2. Now prove that each sig in v_sigs is discharged as false
		//2.1 check that all subsig of a sig is well covered, i.e.,
		// the dnf_step is increasing, it starts from 0 and its
		// last step is equal to dnf_count
		// we do not have to generate the proof for it.
		// note that there is NO need to prove v_sigs is sorted,
		// the well formedness already proves the full coverage
		// of the related dnf_subsig for one sig. If there is one sig
		// shows up multiple times, it's costing more on prover but
		// does not affect soundness of proof.

		//2.2 build subsigs from (sig_id, real_subsig) and lookup
		// (subsig, False) in the (vec_subsig, vec_result) from the
		// previous gen_sytneshsis_subsig_result(). This is needed
		// as the structure of subsigs are different between the 
		// two components.
		let mut map = inp_subsigs.into_iter().zip(subsig_result.into_iter()).
			map(|(x,y)| (*x,*y)).collect::<HashMap<F,F>>();
		let f_false = F::from(TriVal::False as u8);
		map.insert(zero, f_false); //for dummy entry
		let mut v_computed_subsig = vec![zero; n];
		for i in 0..n{
			let subsig_id = F::from(HexACDFA::gen_subsig_id_worker(
						field_to_usize(&v_sigs[i]), 
						field_to_usize(&v_real_subsigs[i])
					) as u128);
			let res = map.get(&subsig_id)
				.expect(&format!("cannot find subsig_id: {}", &subsig_id));
			assert!(*res == f_false, "ERROR: subsig_id: {}, res: {} is not false", subsig_id, res);
			v_computed_subsig[i] = subsig_id;
		}

		let src = encode_cols_better(
			vec![&v_computed_subsig[..], &vec![f_false; n][..]],
			vec![0,1]
		);
		//pad (0,1) for dummy entry
		let pad_subsigs = [&inp_subsigs[..], &vec![zero][..]].concat();
		let pad_res = [&subsig_result[..], &vec![f_false][..]].concat();
		let dst = encode_cols_better(
			vec![&pad_subsigs[..], &pad_res[..]],
			vec![0,1]
		);
		let mtbl_lk_res = gen_m_table(&src, &dst);

		//3. show that inp_sigs is a subset of v_sigs (covered)
		// where we have proved all v_sigs are discharged
		//note: v_sigs is required to have at least one dummy entry at beginning
		let mtbl_sigs= gen_m_table(&inp_sigs, &v_sigs);


		//4. add data columns into containers
		let names = vec![
				"v_sigs", 
				"v_dnf_id", 
				"v_dnf_step", 
				"v_dnf_count", 
				"v_real_subsigs"
				];
		let col2d = vec![
			v_sigs, 
			v_dnf_id, 
			v_dnf_step, 
			v_dnf_count, 
			v_real_subsigs
		];
		col2d.into_iter().zip(names.iter()).for_each(|(c, n)|{
			res.lock().unwrap().add_col(Col::new(c, n, IDX_DATA));
		});
		let col2d_sid = vec![
			v_sid_sigs,  //const
			v_sid_dnf_id,  //const
			v_sid_dnf_step,  //const
			v_sid_dnf_count,  //NOT const
			v_sid_real_subsigs //NOT const
		];
		let bconst_col2d_sid = vec![
			true, true, true, false, false
		];
		col2d_sid.into_iter().zip(names.iter()).zip(bconst_col2d_sid.iter())
		.for_each(|((c, n),b)|{
			if *b{
				res.lock().unwrap().add_col(Col::new_const(
					c, &format!("sid_{}",n), IDX_SI_DATA));
			}else{
				res.lock().unwrap().add_col(Col::new(
					c, &format!("sid_{}",n), IDX_SI_DATA));
			}
		});
		assert!(mtbl_lk_res.len()==n+1);
		res.lock().unwrap().add_col(Col::new(mtbl_lk_res,"mtbl_lk_res",IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n+1],"sid_mtbl_lk_res",
			IDX_SI_DATA));
		
		assert!(mtbl_sigs.len()==n);
		res.lock().unwrap().add_col(Col::new(mtbl_sigs,"mtbl_sigs",IDX_DATA));
		res.lock().unwrap().add_col(Col::new_const(vec![frg;n],"sid_mtbl_sigs",
			IDX_SI_DATA));
		assert!(inp_sigs.len()==capacity.sigs);
		res.lock().unwrap().add_col(Col::new(inp_sigs.clone(),
	 		"discharged_sigs",IDX_DISCHARGED_SIGS)); //no si needed


		Ok(res)
	}


}

impl <F:PrimeField + ColEle> ComputeSigAdvGadget<F>{
	pub fn new(
		fsm_id_cs: u32, //determines which combo to retrieve info
		fsm_id_igc: u32, //determines which combo to retrieve info
		capacity: &ComputeSigAdvCapacity,
		prev_cfgs: &Vec<ContainerConfig>,
		store_steps_cs: &SubsigStepStore,
		store_steps_igc: &SubsigStepStore,
		store_extra_info_cs: &SubsigInfoStore,
		store_extra_info_igc: &SubsigInfoStore,
	)
	-> Self{
		//1. create the dummy input and dummy container config.
		let zero = F::zero();
		let subsigs_cs = vec![zero; capacity.subsigs_cs];
		//skip mode: the real advice gets an empty igc set, the dummy
		//must mirror it (the igc eval is skipped either way)
		let subsigs_igc = if capacity.b_skip_igc { vec![] }
			else { vec![zero; capacity.subsigs_igc] };
		let sigs = vec![zero; capacity.sigs];
		let v_sig_obj: Vec<Arc<ClamavSig>> = vec![]; //empty one
		//make a dummy one
		let discharge_infos = vec![
			DischargeSigInfo{
				sig_name: "none".to_string(),
				b_success: false,
				min_cost: 0,
				min_dnf_id: 0,
				subsig_ids: vec![0],
				subsig_igc: vec![false]
			}; capacity.sigs];

		//2. create the dummy sq_res
		let dis_cap_cs = DischargeAdvCapacity{
			res_small_cost: DischargeAdvCapacity::default_res_small(),
			max_nibble_len: capacity.max_nibble_len,
			subsigs: capacity.subsigs_cs,
			//compute_sig checks the full universe; the dummy acc container
			//(sized off universe_subsigs) must match the real one.
			universe_subsigs: capacity.subsigs_cs,
			avg_active_pats_per_subsig: 2, //it's ok, coz it's not affecting
										  //parse_from
			basis_pats_in_trace: capacity.basis_pats_in_trace_cs,
			perc_pats_expansion_rate: 100,
			b_aggressive: capacity.b_aggressive,
			//dummy: prod = basis_pats*perc keeps the legacy size.
			prod_pats_expansion: capacity.basis_pats_in_trace_cs * 100,
			wrap_keys: 0,
			qm_real_rows: 0,
		};
		let dis_cap_igc= DischargeAdvCapacity{
			res_small_cost: DischargeAdvCapacity::default_res_small(),
			max_nibble_len: capacity.max_nibble_len,
			subsigs: capacity.subsigs_igc,
			universe_subsigs: capacity.subsigs_igc,
			avg_active_pats_per_subsig: 2, //it's ok, coz it's not affecting
										  //parse_from
			basis_pats_in_trace: capacity.basis_pats_in_trace_igc,
			perc_pats_expansion_rate: 100,
			b_aggressive: capacity.b_aggressive,
			prod_pats_expansion: capacity.basis_pats_in_trace_igc * 100,
			wrap_keys: 0,
			qm_real_rows: 0,
		};
		//AGGRESSIVE: the dummy sq_res must be acc_out-shaped (acc_encoded) so
		//gen_eval_subsig_by_acc's external-ref structure (and thus the gadget
		//cfg) matches the real accumulator. Non-aggressive uses a step-queue
		//(sq_res2) dummy.
		let (sq_res_cs, sq_res_igc) = if capacity.b_aggressive {
			let acc_cs = FailedSubsigAcc::<F>{ acc: vec![],
				capacity: Clone::clone(&dis_cap_cs), b_igc: false };
			let acc_igc = FailedSubsigAcc::<F>{ acc: vec![],
				capacity: Clone::clone(&dis_cap_igc), b_igc: true };
			(acc_cs.to_container("failed_acc").expect("dummy acc cs"),
			 acc_igc.to_container("failed_acc").expect("dummy acc igc"))
		} else {
			let step_q_size_cs = StepQueue::<F>::vec_size(
				&StepQueueType::ResSmall, &dis_cap_cs).0;
			let step_q_size_igc= StepQueue::<F>::vec_size(
				&StepQueueType::ResSmall, &dis_cap_igc).0;
			let sq_res_obj_cs = StepQueue::parse_from(
				&vec![zero; step_q_size_cs], StepQueueType::ResSmall,
				&dis_cap_cs, false);
			let sq_res_obj_igc = StepQueue::parse_from(
				&vec![zero; step_q_size_igc], StepQueueType::ResSmall,
				&dis_cap_igc, true);
			(sq_res_obj_cs.to_container("sq_res2_cs", false, true, true, true,
				&store_steps_cs).expect("sq_res_cs err"),
			 sq_res_obj_igc.to_container("sq_res2_igc ", false, true, true,
				true, &store_steps_igc).expect("sq_res_igc err"))
		};
		// AGGRESSIVE seed tie: dummy seed-tie source sized like the
		// real one so compute_sig's mtbl_seed column matches in the cfg.
		// T927 ST neo-aggr: the real source is dan's neo_core, of which
		// gen_eval_subsig_by_acc ext-refs only "subsigs" + "si_subsigs"
		// (si 0 on aggr), so the dummy mirrors those two columns.
		let b_neo_aggr = read_global_config().clamav_cfg
			.b_use_discharge_neo && capacity.b_aggressive;
		let mk_neo_subsigs = |n: usize| {
			let c = Container::<F>::new("neo_core");
			c.lock().unwrap().add_col(Col::new(vec![zero; n],
				"subsigs", IDX_DATA));
			c.lock().unwrap().add_col(Col::new_const(vec![zero; n],
				"si_subsigs", IDX_SI_DATA));
			c
		};
		let (dummy_sq_inp_cs, dummy_sq_inp_igc) = if b_neo_aggr {
			// length MUST equal the real neo_core "subsigs": K slots
			// (subsig_nat is resized to k_slots = capacity.subsigs).
			// compute_sig's mtbl_seed column has K+1 entries (the
			// const 0 first), so a dummy/real size mismatch here makes
			// the main decider snark fail to verify. Sizing this from
			// the DB subsig universe instead made the dummy ~11000x
			// the real column on DLP (2308943 vs 202) -- 92.8% of the
			// neo statement.
			(mk_neo_subsigs(dis_cap_cs.subsigs),
			 mk_neo_subsigs(dis_cap_igc.subsigs))
		} else {
			let sq_inp_size_cs = StepQueue::<F>::vec_size(
				&StepQueueType::ResSmall, &dis_cap_cs).0;
			let sq_inp_size_igc = StepQueue::<F>::vec_size(
				&StepQueueType::ResSmall, &dis_cap_igc).0;
			(StepQueue::parse_from(
				&vec![zero; sq_inp_size_cs], StepQueueType::ResSmall,
				&dis_cap_cs, false)
				.to_container("sq_inp", false, false, false, false,
					&store_steps_cs).expect("dummy sq_inp cs"),
			StepQueue::parse_from(
				&vec![zero; sq_inp_size_igc], StepQueueType::ResSmall,
				&dis_cap_igc, true)
				.to_container("sq_inp", false, false, false, false,
					&store_steps_igc).expect("dummy sq_inp igc"))
		};
		let mut sigs_to_id = HashMap::<String,usize>::new();
		sigs_to_id.insert("none".to_string(), 0);


		//3. create advice
		let dummy_adv = ComputeSigAdvAdvice::new(
			fsm_id_cs,
			fsm_id_igc,
			&sigs,
			&subsigs_cs,
			&subsigs_igc,
			&discharge_infos,
			&sq_res_cs,
			&sq_res_igc,
			&dummy_sq_inp_cs,
			&dummy_sq_inp_igc,
			Clone::clone(&capacity),
			store_steps_cs, 
			store_steps_igc, 
			store_extra_info_cs, 
			store_extra_info_igc, 
			&v_sig_obj, 
			&sigs_to_id,
			0 
		).expect("\n\n===== ***** =======Create dummy advice err. This is system-wide, unable to create circ. Needs to increase capacity as suggested.\n===============\n");
		let mut vec_cfg = prev_cfgs.clone();
		vec_cfg.push(dummy_adv.stmt_container.lock().unwrap().get_cfg());

		//4. other routine ops to set up config vec
		ContainerConfig::adjust_locations(&mut vec_cfg);
		//even it's false, it's good enough for generating statement_structure
		let dummy_cfg = vec_cfg[vec_cfg.len()-1].clone(); //it's the last one

		Self{
			_f: PhantomData, 
			capacity: Clone::clone(capacity), 
			cfgs_context: None,
			my_idx_in_context: None, dummy_cfg,
			job_id: 0
		}
	}

	/// return None if not set yet.
	pub fn get_container_cfg(&self)->Option<ContainerConfig>{
		if self.my_idx_in_context.is_some(){
			let idx = self.my_idx_in_context.unwrap();
			let cfg = self.cfgs_context.as_ref().unwrap().as_ref()[idx].clone();
			Some(cfg)
		}else{
			Some(self.dummy_cfg.clone())
		}
	}

	/// validate raw_eval result based on step queue is correct for
	/// each subsig.
	/// n2 is the StepQueue::vec_size() - max of subsig * avg_active_pat_subsig
	///     and basis_pats_in_trace/10000 * perc_pats_expansion_rate/100 * nlen (see validate_forward_step_queue for
	///     real data for n1)
	/// COST: 6n1 + 5n2 (n1: num of subsigs, n2: sq_res len which
	///    is determined by discharge_adv::StepQueue::vec_size 
	/// (perc_pat_in_trace * perc_pats_expansion_rate / 100)
	/// AGGRESSIVE-ONLY. Validate the membership verdict:
	/// (a) BIND each encoded_last key to inp_subsig via the encode
	///     weighted-sum (sub-fields range-checked via si=RANGE2) so the key
	///     canonically decodes to inp_subsig;
	/// (b) subsig_raw_eval ∈ {False=1, Maybe=3} (dummy subsig=0 exempt);
	/// (c) SOUNDNESS logup: acc_out ⊆ {encoded_last[i] : Maybe} — every
	///     accumulated failed key MUST be marked Maybe, else a real match is
	///     wrongly discharged. (Over-marking Maybe is harmless.)
	fn validate_eval_subsig_by_acc(&self,
		eval_res_combo: &Container<FpVar<F>>,
		r1: FpVar<F>,
		cs: ConstraintSystemRef<F>,
	)->Result<(), SynthesisError>{
		let one = new_const_var(&cs, F::one());
		let three = new_const_var(&cs, F::from(3u64));
		let lb_zero = LinearCombination::from((F::zero(), Variable::One));
		//0. columns
		let get = |nm:&str| eval_res_combo.get_container(nm).unwrap()
			.lock().unwrap().to_vec();
		let inp_subsig = get("inp_subsig");
		let encoded_last = get("inp_subsig_encoded");
		let f_step = get("enc_step");
		let f_pat = get("enc_pat");
		let f_rgs = get("enc_rgs");
		let f_rge = get("enc_rge");
		let subsig_raw_eval = get("subsig_raw_eval");
		let mtbl = get("mtbl_membership");
		let acc_out = eval_res_combo.get_container("acc_ref").unwrap()
			.lock().unwrap().get_container("acc_encoded").unwrap()
			.lock().unwrap().to_vec();
		let n = inp_subsig.len();

		//1. BIND: encoded_last = inp_subsig*f1^4 + step*f1^3 + pat*f1^2
		//   + rgs*f1 + rge. Sub-fields are range-checked (<f1) via si=RANGE2,
		//   so this pins inp_subsig = encoded_last div f1^4 (unique decode).
		verify_encode_cols_in_range(&encoded_last[..],
			&[&inp_subsig[..], &f_step[..], &f_pat[..], &f_rgs[..],
				&f_rge[..]], self.capacity.b_aggressive as usize)?;

		//2. per entry: subsig_raw_eval ∈ {1,3} (dummy subsig=0 exempt);
		//   maybe_masked[i] = encoded_last[i] iff Maybe, else 0.
		let mut maybe_masked = Vec::with_capacity(n);
		let mut v_dummy = Vec::with_capacity(n);
		for i in 0..n{
			let v = &subsig_raw_eval[i];
			let is_dummy = is_zero_better(&inp_subsig[i], &cs).unwrap();
			v_dummy.push(is_dummy.clone());
			let prod = (v - &one) * (v - &three);
			check_prod_zero(&(&one - &is_dummy), &prod, lb_zero.clone(),
				"aggr_raw_eval_in_{1,3}")?;
			let b_maybe = is_zero_better(&(v - &three), &cs).unwrap();
			maybe_masked.push(&encoded_last[i] * &b_maybe);
		}

		//2.5 T961 F1 (W1): d = "inp_subsig_chain" is RANGE2. inp[0] = d[0];
		//inp[i] = inp[i-1] + 1 - is_dummy[i-1] + d[i]; inp[n-1] = d[n].
		//=> zeros form a prefix and nonzero ids strictly ascend, so no
		//subsig owns two slots (a Maybe one absorbing acc, a False one
		//exporting (s,False)). LOAD-BEARING: it is also the range of
		//every inp (sid_inp_subsig is 0): no wrap, as the sum stays
		//< n*(2^rb+1) << p and the last slot is < 2^rb.
		let d = get("inp_subsig_chain");
		assert!(d.len() == n + 1);
		check_eq(&inp_subsig[0], &d[0], "F1 chain start")?;
		for i in 1..n{
			check_eq(&inp_subsig[i], &(&inp_subsig[i-1] + &one
				- &v_dummy[i-1] + &d[i]), "F1 strict ascent")?;
		}
		check_eq(&inp_subsig[n-1], &d[n], "F1 chain end")?;

		//3. SOUNDNESS logup: acc_out subset-of maybe_masked
		assert_logup(cs.clone(), &acc_out, &maybe_masked, &mtbl, &r1)?;

		//4. M7 SEED TIE: every verdict-universe subsig was seeded
		//(replaces QUICK; blocks a False-by-omission verdict).
		//T927 ST (neo): inp_subsig subset-of [0] ++ seed_ref.subsigs,
		//plain ids. seed_ref.subsigs IS dan's neo_core "subsigs" (ext
		//ref, dest None: the same dan statement vars, not in csa's
		//statement, 0 cs), whose every nonzero slot
		//dan anchors to a seeded run (assert_seed_anchors). The const 0
		//absorbs the dummy-0 slots and keeps the table at K+1.
		//EXAMPLE: dan seeds {a}, csa lists [0, a, s] -> s not in
		//  [0, a, 0..] -> UNSAT. Legacy: encode(inp) subset-of sq_inp.
		let seed_ref = eval_res_combo.get_container("seed_ref").unwrap();
		let seed_col = |nm: &str| seed_ref.lock().unwrap()
			.get_container(nm).unwrap().lock().unwrap().to_vec();
		let mtbl_seed = get("mtbl_seed");
		let (qry, tbl) = if read_global_config().clamav_cfg
			.b_use_discharge_neo {
			let mut tbl = vec![FpVar::Constant(F::zero())];
			tbl.extend(seed_col("subsigs"));
			(inp_subsig.clone(), tbl)
		} else {
			let zc: Vec<FpVar<F>> = (0..n)
				.map(|_| new_const_var(&cs, F::zero())).collect();
			(encode_cols_var(&vec![inp_subsig.clone(), zc.clone(),
				zc.clone(), zc.clone(), zc], &vec![0,1,2,3,4]),
			 seed_col("encoded"))
		};
		assert_logup(cs.clone(), &qry, &tbl, &mtbl_seed, &r1)?;
		Ok(())
	}

	fn validate_eval_subsig_by_sq_combo(&self,
		eval_res_combo: &Container<FpVar<F>>,
		r1: FpVar<F>,
		_r2: FpVar<F>,
		cs: ConstraintSystemRef<F>
	) ->Result<(), SynthesisError>{
		//AGGRESSIVE: verdict comes from accumulator membership, not sq_res.
		if self.capacity.b_aggressive{
			return self.validate_eval_subsig_by_acc(eval_res_combo, r1, cs);
		}
		//0. retrieve data from combo
		let b_perf = false;
		let nc = cs.num_constraints();
		let (_zero,one)=(new_const_var(&cs,F::zero()),new_const_var(&cs,F::one()));
		let names = ["inp_subsig", "last_step", "subsig_raw_eval", 
			"inp_subsig_encoded"];
		let cols = names.iter().map(|n|
			eval_res_combo.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (inp_subsig, last_step, subsig_raw_eval, inp_subsig_encoded) = 
			(&cols[0],&cols[1],&cols[2], &cols[3]);
		let sid_cols = names.iter().map(|n|
			eval_res_combo.get_container(&format!("sid_{}",n))
				.unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let sid_last_step = &sid_cols[1]; //only need to check this
			
		//1. extract subsig, last_step from sq_res 
		let sq_res=eval_res_combo.get_container("sq_res")
			.expect("err get sq_res"); //it's actually 
						//externally refered copy (do not take space)
		let names = ["subsig", "step", "encoded"];
		let cols = names.iter().map(|n| 
			sq_res.lock().unwrap().get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (sq_subsig, sq_step, sq_encoded) = (&cols[0], &cols[1], &cols[2]);
		let sq_sid_step = sq_res.lock().unwrap().get_container("si_step")
			.unwrap().lock().unwrap().to_vec();
		let n2 = cols[0].len();

		//2. proof step1: assert that (encoded, subsig, last_step, sid_last_step) 
		// is the valid
		//from sq_res. only need one-direction lookup, since if there
		//are subsigs missed from sq_res, they won't show up in the
		//final evaluation result anyway (and cannot be discharged).
		//it's the loss of prover,and cannot affect soundness (but likley
		//raise false alarm). So it's ok to do 1-direction lookup
		// COST: 5n1 + 8n2 (where n1 is subsigs, n2 is sq_res length) [old]
		// --> cost improved by using f_unit (we didn't change formula here)
		//TODO: can be improved by calling combined_logup function
		// and just add padding zero.
		let f_unit = FpVar::<F>::constant(F::from(1u32<<read_global_config().range2_bit));
		let src= encode_cols_var_adv_better(&vec![&inp_subsig_encoded[..],
			&inp_subsig[..], &last_step[..], &sid_last_step], &vec![0,1,2,3], 
				&f_unit);
		let dst_sel = (0..n2).into_iter().map(|i|{
			if i==n2-1{one.clone()} else{ 
				//sq_subsig[i].is_neq(&sq_subsig[i+1]).unwrap().into() 
				&one- is_zero_better(&(&sq_subsig[i]-&sq_subsig[i+1]),
					&cs).unwrap()
			}
		}).collect::<Vec<FpVar<F>>>();
		let dst_combined = encode_cols_var_adv_better(
			&vec![&sq_encoded[..], &sq_subsig[..], &sq_step[..], 
				&sq_sid_step[..]], &vec![0,1,2,3], &f_unit);
		let dst = dst_combined.iter().zip(dst_sel.iter()).map(|(a,b)|
			a * b).collect::<Vec<FpVar<F>>>();
		let mtbl_last_step = eval_res_combo.get_container("mtbl_last_step")
			.unwrap().lock().unwrap().to_vec();
		assert_logup(cs.clone(), &src, &dst, &mtbl_last_step, &r1)?;

		//3. proof step2: verify that eval_res is correct.
		//to save cost: assert eval_res is boolean (either 1 or 0)
		//and then use it to enforce sid_last_step == sid for MAX_STEP
		//COST: 5n1  where n1 is the number of subsigs
		let info_id= F::from(0x23001101u32); //tag to avoid collision
		let f1 = F::from(1u64<<read_global_config().range2_bit);
        let factor1 = f1*f1*f1*f1*f1; //models encoded
        let factor2 = F::from(1u64<<32); //32-bit
		let part1 = info_id*factor1*factor2 + 
			F::from(ID_ENCODED_NORMAL_STEP)*factor1;
		let part1_alt = info_id*factor1*factor2 + 
			F::from(ID_ENCODED_LAST_STEP)*factor1;
		let part1_normal_var = new_const_var(&cs, part1);
		let part1_last_var = new_const_var(&cs, part1_alt);
		if B_DEBUG { assert!(TriVal::False as u8==1u8 && TriVal::Maybe as u8==3);}

		let lb_zero= LinearCombination::from((F::zero(),Variable::One));
		for i in 0..subsig_raw_eval.len(){
			//3.1 NOTE eval has two possible values:
			// subsig_raw_val is ALREADY PROVED to be either ONE of
			// TriVal::False (1), or Trival::Maybe (3)
			// b_last_step should be true when v is 3 (Maybe) and false if v=1.
			//let b_last_step = subsig_raw_eval[i].is_neq(&one)?;
			let b_last_step = &one - is_zero_better(&(&subsig_raw_eval[i]-&one),&cs).unwrap();

			//3.3 retrieve existing tag (note that we've already proved
			//that it is projected from sq_res, and also sq_res has already
			//proved the validity of sid_step - thus it's the VALID step ID
			//already proved).
			let valid_sid = &sid_last_step[i];

			//3.2 build the ACTUAL sid_tag  from subsig_raw_eval
			//as a nondeterministic advice. We'll verify its correctness
			//let part1 = b_last_step.select(&part1_last_var, &part1_normal_var)?;
			let part1_val = if b_last_step.value()?==F::one(){
				part1_last_var.value()?
			}else{
				part1_normal_var.value()?
			};
			let part1 = new_var(&cs, part1_val);
			// we assert b_last * (part1-last_var) + (1-b_last)*(part1-normal)=0
			// i.e. b_last * (last_var -normal)  = part1 - normal 
			let lb_last_step = var_to_lb(&b_last_step, F::one());
			let lb_neg_normal = var_to_lb(&part1_normal_var, -F::one());
			let lb_part1 = var_to_lb(&part1, F::one());
			let lb_last_var = var_to_lb(&part1_last_var, F::one());
			cs.enforce_constraint(
				lb_last_step,
				lb_last_var + lb_neg_normal.clone(),
				lb_part1 + lb_neg_normal
			)?;

			let sid_act = &part1 + &inp_subsig_encoded[i];
			//let diff = &inp_subsig[i]*&(&sid_act - valid_sid);
			//check_eq(&diff, &zero, "sid check failed")?; //only required for 
													//non-zero "real" entries
			let lb_sid_act = var_to_lb(&sid_act, F::one());
			let lb_neg_valid_sid = var_to_lb(&valid_sid, -F::one());
			let lb_inp_subsig = var_to_lb(&inp_subsig[i], F::one());
			if B_DEBUG {
				assert!(inp_subsig[i].value()? * (sid_act.value()?-
					valid_sid.value()?)==F::zero());
			}
			
			cs.enforce_constraint(
				lb_inp_subsig,
				lb_sid_act + lb_neg_valid_sid,
				lb_zero.clone()
			)?;
		}

		if b_perf{
			println!(" ### validate_eval_subsig_by_sq_combo: subsigs: {}, sq_res.len: {}, cost: {}", inp_subsig.len(), sq_encoded.len(), cs.num_constraints()-nc); 
		}

		Ok( () )
	}

	/// validate syntesis of subsig is correct.
	/// COST:  let n = number of subsigs, n2 = scc table size (20% of n at most
	///				in practice) = perc_scc * subsigs
	/// 29*n + 69*n2 (given n2<20%*n) ==> 43n (number of subsigs)
	///   + additional cs/igc cost 6n = 49n.
	/// in practice: this is 1000 *49 = 49k R1CS
	/// UPDATED: around 35n (when perc_copm_subsigs is 20%)
	fn validate_synthesis_subsig_combo(&self, 
		eval_res_combo_cs: &Container<FpVar<F>>, 
		eval_res_combo_igc: &Container<FpVar<F>>, 
		synthesis_res_combo: &Container<FpVar<F>>, 
		r1: FpVar<F>,
		cs: ConstraintSystemRef<F>
	) ->Result<(), SynthesisError>{
		//0. retrieve data from combo
		let b_debug = B_DEBUG;
		let b_perf = false;
		let nc = cs.num_constraints();
		let (zero,one)=(new_const_var(&cs,F::zero()),new_const_var(&cs,F::one()));
        let max_val:usize = (1<<read_global_config().range2_bit) - 1;
		let max=new_const_var(&cs,F::from(max_val as u64));
		let frg = new_const_var(&cs, F::from(RANGE2));
		let names = ["vec_op", "vec_num", "vec_counter_res", "vec_type"];
		let cols = names.iter().map(|n|
			synthesis_res_combo.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (vec_op, vec_num, vec_counter_res, vec_type) = (&cols[0], 
			&cols[1], &cols[2], &cols[3]);
		let names = ["sid_op", "sid_num", "vec_sid_type"];
		let sid_cols = names.iter().map(|n|
			synthesis_res_combo.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (vec_sid_op, vec_sid_num, vec_sid_type) = 
			(&sid_cols[0], &sid_cols[1], &sid_cols[2]); // no need
						//to check sid_counter_res as it's computed in circ
		//let v_igc = synthesis_res_combo.get_container("v_igc")
		//	.unwrap().lock().unwrap().to_vec();
		//let v_sid_igc = synthesis_res_combo.get_container("v_sid_igc")
		//	.unwrap().lock().unwrap().to_vec();
		let n = vec_op.len();
		assert!(vec_num.len()==n && vec_counter_res.len()==n);

		//1. verify the correctness of inp_subsigs with gen_regex_res
		//NOTE that we simply retrieve from the eval_res_combo of
		//cs version and igc version. One slot per subsig overall: per list
		// by F1 (strict ascent, aggr; nonaggr after T960), across lists by
		// the NH3 arm TYPE tag below (T961; the old union proof was vacuous).
		let input_subsigs_cs= eval_res_combo_cs
			.get_container("inp_subsig").unwrap().lock().unwrap().to_vec();
		let input_subsigs_igc= if self.capacity.b_skip_igc { vec![] }
			else { eval_res_combo_igc
			.get_container("inp_subsig").unwrap().lock().unwrap().to_vec() };
		let inp_subsigs = vec![&input_subsigs_cs[..], &input_subsigs_igc[..]]
			.concat();
		let gen_regex_res_cs = eval_res_combo_cs
			.get_container("subsig_raw_eval").unwrap().lock().unwrap().to_vec();
		let gen_regex_res_igc = if self.capacity.b_skip_igc { vec![] }
			else { eval_res_combo_igc
			.get_container("subsig_raw_eval").unwrap().lock().unwrap().to_vec() };
		let gen_regex_res = vec![&gen_regex_res_cs[..], &gen_regex_res_igc[..]]
			.concat();
		assert!(inp_subsigs.len()==gen_regex_res.len());
		assert!(inp_subsigs.len() == n);


		//2. verify the result of counter constraint 
		// the structure for each subsig is
		// (num, op, counter_res) where counter_res is defined using
		// logic: case op
		// NONE => raw_res (note: this is like don't care value anyway) 
		// LT => !raw_res
		// EQ => if num!=0 {raw_res} else {!raw_res}
		// GT => raw_res
		// ------ simplifying the above, we have
		// ct_res = if op==LT || (op=EQ && num==0) {!raw_res}
		//			else {raw_res}
		// consider how to express the if condition:
		// op==EQ && num==0 can be checked using random factor r1 like
		//   (op-EQ) + r1*num == 0 [only when both op==EQ and num==0
		//   it has large probability of equal to zero.
		// So the if condition is:
		//  (op-LT) * ( (op-EQ) + r1 * num ) == 0
		// this costs: 2 + is_eq: 3 = 5 constraints. This looks like
		// the least costly solution. Otherwise raw encoding using Boolean
		// directly costs: 3 is_eq: 6 + one and: 1 + one or: 3 = 10 constraints

		//2.1 verify the validity of vec_op and vec_num (the op is retrieved from
		// the database for the subsig. Mainly we are recomputing
		// their SID using the algorithm of 
		// SubsigInfoStore::gen_info_tbl_id() in clam_db.rs
		// COST: 3n (where n is the number of subsigs)
		let info_id:u32 = 0x13752405; //just random tag to avoid collision
		let f1 = F::from(info_id);
		let factor = F::from(0x100000000 as u64); //32-bit 
		let f1_var = new_const_var(&cs, f1);
		let factor_var = new_const_var(&cs, factor);
		let part1 = &(&f1_var * &factor_var) * &factor_var;
		let piece_op = new_const_var(&cs, F::from(ID_COMP_OP as u32)); 
		let piece_num = new_const_var(&cs, F::from(ID_COMP_NUM as u32)); 
		let piece_type= new_const_var(&cs, F::from(ID_SUBSIG_TYPE as u32)); 
		//NH3 (T961): arm tag, cs slots first then igc slots
		let piece_type_igc = new_const_var(&cs,
			F::from(ID_SUBSIG_TYPE_IGC as u32));
		let n1_cs = input_subsigs_cs.len();
		for i in 0..n{//non-constants
			let f3 = &inp_subsigs[i];
			let f3_fac = f3 * &factor_var; 
			let prefix = &part1 + &f3_fac;
			let exp_sid_op = &prefix + &piece_op;
			let exp_sid_num = &prefix + &piece_num;
			let exp_sid_type= &prefix +
				if i < n1_cs {&piece_type} else {&piece_type_igc};
			check_eq(&exp_sid_op, &vec_sid_op[i], "sid_op check fails")?;
			check_eq(&exp_sid_num, &vec_sid_num[i], "sid_num check fails")?;
			check_eq(&exp_sid_type, &vec_sid_type[i], "sid_type check fails")?;
		}

		//2.2 verify the calculation of counter_res is correct.
		// cost: 9n -> improved to 7n
		let lb_zero= LinearCombination::from((F::zero(),Variable::One));
		let eq_var = new_const_var(&cs, F::from(CompOp::EQ as u8));
		let lt_var = new_const_var(&cs, F::from(CompOp::LT as u8));
		let three_var = new_const_var(&cs, F::from(3u8));
		let six_var = new_const_var(&cs, F::from(6u8));
		for i in 0..n{
			//2.2.1 compute the condition
			// cost: 5n
			let cond = &(&vec_op[i] - &lt_var) * 
				&(&(&vec_op[i]-&eq_var) + &(&r1 * &vec_num[i]));
			//let b_cond = cond.is_zero()?;
			let b_cond = is_zero_better(&cond, &cs)?;

			//2.2.2 compute the neg_res
			//we create the using as non-deterministic advice
			//then verify that it's correct. This saves 1 constraint.
			//idea: raw_res is already proved (so we are ensured that
			//  it is either False (1) or Maybe (3).
			// Consider all combinations of two value added up.
			//  False + True = 3, True + False = 3
			//  Maybe + Maybe = 6.
			// These are the ONLY VALID combinations.
			// cost: 2n
			let res_val = gen_regex_res[i].value()?;
			//handle special 0 dummy value for dummy subsig 0
			let tri_res_val = if res_val.is_zero() {TriVal::Maybe}
			else {TriVal::from(field_to_usize(&res_val) as u8)};
			let neg_res_val = (!tri_res_val) as u8;
			let raw_res = &gen_regex_res[i];
			let neg_raw_res = new_var(&cs, F::from(neg_res_val));
			check_eq(&(&(raw_res+&neg_raw_res-&three_var)*
				&(raw_res+&neg_raw_res-&six_var)), &zero, "error checking neg")?;

			//2.2.3 enforce the conditional assignment
			// counter_res = if i_condition {!raw_res} else {raw_res}
			// cost: 3n
			//let exp_res = b_cond.select(&neg_raw_res, raw_res)?;
			// ignore subsig 0 case as it's dummy
			//check_eq(&(&inp_subsigs[i]*&(&exp_res- &vec_counter_res[i])), 
			//	&zero, "err counter_res")?;
			let exp_res_val = if b_cond.value()? == F::one(){
				neg_raw_res.value()?
			}else{
				raw_res.value()?
			};
			let exp_res = new_var(&cs, exp_res_val);
			if B_DEBUG {
				assert!(inp_subsigs[i].value()? *
					(exp_res.value()? - vec_counter_res[i].value()?)
				==F::zero());
			}
			//opt 1: enforce bcond.select ...
			// b_cond *(neg_raw_res-raw_res) = exp_res - raw_res
			let lb_neg_raw_res = var_to_lb(&neg_raw_res, F::one());
			let lb_minus_raw_res = var_to_lb(&raw_res, -F::one());
			let lb_b_cond = var_to_lb(&b_cond, F::one());
			let lb_exp_res = var_to_lb(&exp_res, F::one());
			cs.enforce_constraint(
				lb_b_cond,
				lb_neg_raw_res + lb_minus_raw_res.clone(),
				lb_exp_res.clone() + lb_minus_raw_res
			)?;
			//opt2 enforce check_eq(inp_subsigs[i] * (exp_res - vec_conter[i)
			let lb_inp_subsig = var_to_lb(&inp_subsigs[i], F::one());
			let lb_neg_counter_res = var_to_lb(&vec_counter_res[i], -F::one());
			cs.enforce_constraint(
				lb_inp_subsig,
				lb_exp_res + lb_neg_counter_res,
				lb_zero.clone()
			)?;
		}

		//3. the SubsigCountConstraint part
		//n2 is up to 20% of n (subsigs) in practice
		//3.1 retrieve the cols and sid cols, and check validity
		//of sid columns, so that we are checking the validity of comp_subsigs
		//and their min_req by leveraging the database saved in external lkup
		//
		//-- 3.1.0 retrieve data
		//COST: 0*n2 
		let n2 = self.capacity.get_scc_prf_size();
		let names = vec![
			"scc_prf_subsig", "scc_prf_comp_subsig_encode", 
			"scc_prf_comp_subsig",
			"scc_prf_min_req", "scc_prf_raw", "scc_prf_cnt_true",
			"scc_prf_cnt_maybe", "scc_prf_row_res",
			"scc_prf_abs_diff1", "scc_prf_abs_diff2",
		];
		let col2d = names.iter().map(|n|
			synthesis_res_combo.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let sid_names = vec![ "sid_scc_prf_comp_subsig_encode", 
			"sid_scc_prf_comp_subsig", "sid_scc_prf_min_req",
			"sid_scc_prf_abs_diff1", "sid_scc_prf_abs_diff2"
		];
		let sid_col2d = sid_names.iter().map(|n|
			synthesis_res_combo.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (sid_scc_prf_comp_subsig_encode, sid_scc_prf_comp_subsig, 
			sid_scc_prf_min_req, _sid_scc_prf_abs_diff1, _sid_scc_prf_abs_diff2)
		= (&sid_col2d[0], &sid_col2d[1], &sid_col2d[2], 
			&sid_col2d[3], &sid_col2d[4]);

		//-- 3.1.1 check the sid columns
		//COST: 8*n2
		let piece_comp = new_const_var(&cs, F::from(ID_COMP_SUBSIG as u32)); 
		let piece_min = new_const_var(&cs, F::from(ID_MIN_REQUIRED as u32)); 

		for i in 0..n2{
			//3.1.1.1 check sid_comp_encode (simulating the computation of gen_info_tbl_id)
			// also the sid_comp_min_required
			let f3 = &col2d[0][i]; //the subsig
			let f3_fac = f3* &factor_var; //factor_var from 2.1 
			let prefix = &part1 + &f3_fac;
			let exp_sid_comp = &prefix + &piece_comp;
			let exp_sid_min = &prefix + &piece_min;
			check_eq(&(f3*&(&exp_sid_comp-&sid_scc_prf_comp_subsig_encode[i])), &zero,
				"sid_comp_encoded err")?;
			check_eq(&(f3*&(exp_sid_min-&sid_scc_prf_min_req[i])), &zero,"sid_min err")?;
			check_eq(&(f3*&(&sid_scc_prf_comp_subsig[i]-&frg)),&zero,"sid_comp_subsig err")?;
			//no need to check onstant sids
			//check_eq(&sid_scc_prf_abs_diff1[i], &frg, "sid_abs_diff1 err")?;
			//check_eq(&sid_scc_prf_abs_diff2[i], &frg, "sid_abs_diff2 err")?;
		}

		//-- 3.1.2 check the validity of sid_comp_count
		// count is computed from comp_subsit_encode and comp_subsig (which
		// already have range prf).
		// verify count increase by 1 if subsig is the same and
		// starts from 1 for a new_subsig in the sequence. With the
		// DB-bound max row (vec_cnt = k+1) this guarantees that a
		// block read by 3.5 covers ALL of vec_comp.
		//
		// COST: 10*(n2-1) + 1
		let fa_var = new_const_var(&cs, F::from(1u32 << read_global_config().range2_bit));
		let vec_cnt = col2d[1].iter().zip(col2d[2].iter()).map(|(c1,c2)|{
			c1 - &(c2 * &fa_var)
		}).collect::<Vec<FpVar<F>>>();
		let row0_null = col2d[0][0].value()?.is_zero();
		#[cfg(test)] // T965 seam S2 (test only): NH2 disarms this native check
		let row0_null = row0_null
			|| !tests_compute_sig_adv::t965_native_guard("scc_prf_row0");
		assert!(row0_null, "scc_prf too small, need 1st entry to be null entry. adjust perc_comp_subsigs in Config!");
		//T964 NH2: the chain below starts at row 1, so pin row 0 to a pad
		check_eq(&col2d[0][0], &zero, "scc_prf row 0 is the null entry")?;
		let tri_true:FpVar<F> = 
			new_const_var(&cs, F::from(TriVal::True as u8)).into();
		let tri_maybe:FpVar<F> = 
			new_const_var(&cs, F::from(TriVal::Maybe as u8)).into();
		let tri_false:FpVar<F> = 
			new_const_var(&cs, F::from(TriVal::False as u8)).into();
		for i in 1..n2{
			let subsig = &col2d[0][i];
			let prev_subsig = &col2d[0][i-1];
			let diff_sid = subsig-prev_subsig;
			//let same_subsig:FpVar<F> = diff_sid.is_zero()?.into(); //1 or 0
			let same_subsig:FpVar<F> = is_zero_better(&diff_sid, &cs)?; //1 or 0
			//let is_raw_true:FpVar<F> = col2d[4][i].is_eq(&tri_true)?.into();
			let is_raw_true:FpVar<F> = is_zero_better(
				&(&col2d[4][i]-&tri_true), &cs)?;
			//let is_raw_maybe:FpVar<F> = col2d[4][i].is_eq(&tri_maybe)?.into();
			let is_raw_maybe:FpVar<F> = is_zero_better(
				&(&col2d[4][i]-&tri_maybe), &cs)?;
			//T964 H2': a block starts on ANY row whose subsig differs
			//from the previous one (pad or not), so every real block
			//starts at vec_cnt 1 with cnt = is_raw:
			//(1) real row: vec_cnt = 1 + same*vec_cnt[i-1]
			//(2) every row: cnt = is_raw + same*cnt[i-1] (honest pads
			//    are all 0 and come first, so no gate is needed)
			//No "block ends at max" check: a comp==max row (the only
			//3.5 dst rows) is DB-bound to vec_cnt = k+1, so the block
			//before it is exactly the k components of vec_comp.
			let same_cnt = &same_subsig * &vec_cnt[i-1];
			check_prod_zero(subsig, &(&vec_cnt[i] - &one - &same_cnt),
				LinearCombination::zero(), "scc vec_cnt: +1 or start from 1")?;
			check_prod_eq(&same_subsig, &col2d[5][i-1],
				&(&col2d[5][i] - &is_raw_true), "scc cnt_true chain")?;
			check_prod_eq(&same_subsig, &col2d[6][i-1],
				&(&col2d[6][i] - &is_raw_maybe), "scc cnt_maybe chain")?;
		}

		//3.2 lookup (comp_subsig, raw_res) in the gen_regex_res
		// to prove the validity of raw_res for the comp_subsig
		// ignore the max entries
		//
		// COST: n2 +  3*n2 + n2 + n + 2n2 + 3n
		// = 7*n2 + 4*n (where n2 is scc_prf_size and n is subsigs) 
		// in practice n2 is at most 20% of n1.
		// as cols are all in RANGE2, just use f_unit to do combination
		// improved to 5*n2 + 4*n
		let f_unit = FpVar::<F>::constant(F::from(1u32<<read_global_config().range2_bit));
		let src_s_r = encode_cols_var_adv_better(
			&vec![&col2d[2][..],&col2d[4][..]], //comp_subsig and raw
			&vec![0,1],
			&f_unit
		);
		//is_max: comp_subsig == max (the block's last row), shared with 3.5
		let is_max = col2d[2].iter().map(|c|
			is_zero_better(&(c-&max), &cs).unwrap()
		).collect::<Vec<FpVar<F>>>();
		let src_sel = is_max.iter().map(|b_eq| &one - b_eq)
			.collect::<Vec<FpVar<F>>>();
		let src_s_r = src_s_r.iter().zip(src_sel.iter()).map(|(a,b)|
			a * b).collect::<Vec<FpVar<F>>>();
		let dest_s_r = encode_cols_var_adv_better(
			&vec![&inp_subsigs[..], &gen_regex_res[..]],
			&vec![0,1],
			&f_unit
		);
		let mtbl_comp_score = synthesis_res_combo.get_container("mtbl_comp_score").unwrap().lock().unwrap().to_vec();
		assert_logup(cs.clone(), &src_s_r, &dest_s_r, &mtbl_comp_score, &r1)?;


		//3.3. check abs_diff is ok: idea: do the real diff and check
		//their square equal. Note that the sid of abs_diff is already
		//checked earlier.
		//
		//COST: 6*n2
		let lb_zero= LinearCombination::from((F::zero(),Variable::One));
		for i in 0..n2{
			let subsig = &col2d[0][i];
			let diff1 = &col2d[5][i] - &col2d[3][i]; //cnt_true - min_req
			let abs_diff1 = &col2d[8][i];
			let res1 = &diff1*&diff1 - abs_diff1*abs_diff1;
			//enforce those for real entries, i.e., subsig!=0
			//check_eq(&(subsig*(&res1-&zero)), &zero, "err on abs_diff1")?;
			let lb_res1 = var_to_lb(&res1, F::one());
			let lb_subsig = var_to_lb(&subsig, F::one());
			cs.enforce_constraint(
				lb_res1,
				lb_subsig.clone(),
				lb_zero.clone()
			)?;

			//diff2 = min_req - (cnt_maybe + cnt_true + 1)
			let diff2 = &col2d[3][i] - &one - &col2d[5][i] - &col2d[6][i];
			let abs_diff2 = &col2d[9][i];
			let res2 = &diff2*&diff2 - abs_diff2*abs_diff2;
			//check_eq(&(subsig*(&res2-&zero)), &zero, "err on abs_diff2")?;
			let lb_res2 = var_to_lb(&res2, F::one());
			cs.enforce_constraint(
				lb_res2,
				lb_subsig.clone(),
				lb_zero.clone()
			)?;
		}


		//3.4 validate the row_res
		//Logic: three cases: 
		//(1) cnt_true - min_req>=0, i.e., abs_diff1 = cnt_true-min_req
		//  <==> True
		//(2) cnt_true + cnt_maybe < min_req, i.e.,
		//     abs_diff2 = min_req - cnt_true - cnt_maybe - 1
		//  <==> False
		//(3) O.t. Maybe
		//Given that n2 is small (in practice up to 20% of 1000 subsigs) = 200
		//we didn't optimize just use boolean selector
		//
		// COST: 9*n2
		for i in 0..n2{
			let b_case1 = (&col2d[5][i] - &col2d[3][i]).is_eq(&col2d[8][i])?;
			let b_case2 = (&col2d[3][i] - &col2d[5][i] - &col2d[6][i] - &one)
				.is_eq(&col2d[9][i])?;
			let exp_res = b_case1.select(&tri_true,
				&b_case2.select(&tri_false, &tri_maybe)?)?;
			let row_res = &col2d[7][i];
			let subsig = &col2d[0][i];
			//check_eq(&(subsig*(row_res-exp_res)), &zero, "err on row_res")?;
			let lb_res= var_to_lb(&row_res, F::one());
			let lb_exp_res= var_to_lb(&exp_res, -F::one());
			let lb_subsig = var_to_lb(&subsig, F::one());
			cs.enforce_constraint(
				lb_res + lb_exp_res,
				lb_subsig.clone(),
				lb_zero.clone()
			)?;
		}

		//3.5 check the validity of vec_scc_res, leveraging vec_type	
		//COST: n: subsigs, n2: scc_table (which is usually up to 20% of n)
		//  6n + 3*n2 (is_max shared with 3.2)
		let vec_scc_res= synthesis_res_combo.get_container("vec_scc_res")
			.unwrap().lock().unwrap().to_vec();
		let mtbl_find_scc_res= synthesis_res_combo
			.get_container("mtbl_find_scc_res").unwrap().lock().unwrap().to_vec();
		let var_scc = new_const_var(&cs, 
			F::from(SubSigType::SubsigCountConstraint as u8)); //it's 2
		let is_scc= vec_type.iter().map(|t|
			//t.is_eq(&var_scc).unwrap()
			is_zero_better(&(t-&var_scc), &cs).unwrap()
		).collect::<Vec<FpVar<F>>>();
		let src_sel = is_scc.iter().map(|t| 
			t.clone().into()).collect::<Vec<FpVar<F>>>();
		assert!(vec_scc_res.len()==n && src_sel.len()==n);
		let src = encode_cols_var_adv_better(
			&vec![&inp_subsigs[..], &vec_scc_res[..]],
			&vec![0,1],
			&f_unit
		);
		let src = src.iter().zip(src_sel.iter()).map(|(a,b)|
			a * b).collect::<Vec<FpVar<F>>>();

		let dst= encode_cols_var_adv_better(//scc_prf_subisg and scc_prf_row_res
			&vec![&col2d[0][..], &col2d[7][..]],
			&vec![0,1],
			&f_unit
		);
		let dst = dst.iter().zip(is_max.iter()).map(|(a,b)| //comp == max
			a * b).collect::<Vec<FpVar<F>>>();

		assert_logup(cs.clone(), &src, &dst, &mtbl_find_scc_res, &r1)?;

		//4. VERIFY the final table. idea is simple: we
		// use conditional selection to determine based on type
		//
		// COST: 7n 
		let var_regular = new_const_var(&cs,
			F::from(SubSigType::GeneralRegex as u8)); // 0
		let is_reg = vec_type.iter().map(|t|
			//t.is_eq(&var_regular).unwrap()
			is_zero_better(&(t-&var_regular), &cs).unwrap()
		).collect::<Vec<FpVar<F>>>();
		assert!(vec_scc_res.len()==n);
		assert!(gen_regex_res.len()==n);
		assert!(vec_counter_res.len()==n);
		let vec_subsig_final_res = synthesis_res_combo
			.get_container("vec_subsig_final_res").unwrap().lock().unwrap().to_vec();
		for i in 0..n{//since it's small about 1k entries, just single thread
			let subsig = &inp_subsigs[i];
			//let res = is_scc[i].select(&vec_scc_res[i],
			//	&is_reg[i].select(&gen_regex_res[i],
			//		&vec_counter_res[i]).unwrap()
			//).unwrap();
			let res = better_select(&is_scc[i], &vec_scc_res[i],
				&better_select(
					&is_reg[i], &gen_regex_res[i], &vec_counter_res[i]
				)
			);
			//check_eq(&(subsig*&(&res-&vec_subsig_final_res[i])),
			//	&zero, "fail final subsig")?;
			check_prod_zero(&subsig, &(&res-&vec_subsig_final_res[i]),
				lb_zero.clone(), "fail final subsig")?;
		}


		if b_perf{
			println!(" ### validate_syntehsis_subsig_combo: subsigs: {}, scc_tbl_size: {}, cost: {}", n, n2, cs.num_constraints()-nc);
		}
		Ok( () )
	}

	/// validate syntesis of subsig is correct.
	///
	/// COST: 2*n1 +  16*n
	/// where (n1 = num of sigs, n = num of subsigs)
	/// in real data: worst case n1 = 300, n = 1000 (=> worst case: 23k)
	fn validate_discharge_sig_combo(&self, 
		eval_res_combo_cs: &std::sync::Arc<std::sync::Mutex<Container<FpVar<F>>>>, 
		eval_res_combo_igc: &std::sync::Arc<std::sync::Mutex<Container<FpVar<F>>>>, 
		synthesis_res_combo: &std::sync::Arc<std::sync::Mutex<Container<FpVar<F>>>>, 
		discharge_sig_combo: &std::sync::Arc<std::sync::Mutex<Container<FpVar<F>>>>, 
		r1: FpVar<F>,
		_r2: FpVar<F>,
		cs: ConstraintSystemRef<F>
	) ->Result<(), SynthesisError>{
		//0. retrieve data from combo
		let b_perf = false;
		let nc = cs.num_constraints();
		let b_debug = B_DEBUG;
		let (zero,one)=(new_const_var(&cs,F::zero()),
			new_const_var(&cs,F::one()));
        let max_val:usize = (1<<read_global_config().range2_bit) - 1;
		let _max=new_const_var(&cs,F::from(max_val as u64));
		let _frg = new_const_var(&cs, F::from(RANGE2));
		let names = vec![ "v_sigs", "v_dnf_id", "v_dnf_step", 
			"v_dnf_count", "v_real_subsigs"];
		let cols = names.iter().map(|n|
			discharge_sig_combo.lock().unwrap()
				.get_container(n).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (v_sigs, v_dnf_id, v_dnf_step, v_dnf_count, v_real_subsigs) = (
			&cols[0], &cols[1], &cols[2], &cols[3], &cols[4]);
		let sid_cols = names.iter().map(|n|
			discharge_sig_combo.lock().unwrap()
				.get_container(&format!("sid_{}",n)).unwrap().lock().unwrap().to_vec()
		).collect::<Vec<Vec<FpVar<F>>>>();
		let (_v_sid_sigs, _v_sid_dnf_id, _v_sid_dnf_step, v_sid_dnf_count, 
			v_sid_real_subsigs) = (&sid_cols[0], &sid_cols[1], &sid_cols[2], 
				&sid_cols[3], &sid_cols[4]);
		let n = v_sigs.len();
		for i in 0..cols.len(){assert!(cols[i].len()==n);}
		for i in 0..cols.len(){assert!(sid_cols[i].len()==n);}

		//1. check the validity of sid cols (sequential as circ does not
		//allow parallelism)
		//
		// Cost: 5n
		let info_id:u32 = 0x98882405; 
		let f1_val = F::from(info_id);
		let factor_val = F::from(0x100000000 as u64); //32-bit 
		let factor = new_const_var(&cs, factor_val);
		let factor2 = &factor * &factor;
		let factor3 = &factor * &factor2;
		let f1 = new_const_var(&cs, f1_val);
		let part1 = &f1 * &factor3;

		let info_id:u32 = 0x99992405; 
		let f1_2 = new_const_var(&cs, F::from(info_id));
		let part1_2 = &f1_2 * &factor3;

		for i in 0..n{//no need to check constants
			//check_eq(&v_sid_dnf_id[i], &frg, "err sid dnf_id")?;
			//check_eq(&v_sid_dnf_step[i], &frg, "erro sid_dnf_step")?;
			//check_eq(&v_sid_sigs[i], &frg, "err id_sig")?;

			let sig_prod = &v_sigs[i] * &factor2;
			let dnf_id_prod = &v_dnf_id[i] * &factor;
			let exp_sid_dnf_count = &part1 + &sig_prod + &dnf_id_prod;
			check_eq(&exp_sid_dnf_count, &v_sid_dnf_count[i], 
				"err sid_dnf_cnt")?;

			let exp_sid_real_subsig = &part1_2 + &sig_prod + &dnf_id_prod
				+ &v_dnf_step[i];
			check_eq(&exp_sid_real_subsig, &v_sid_real_subsigs[i],
				"err sid_real_subsig")?;
		}

		//2. Now prove that each sig in v_sigs is discharged as false
		//2.1 check that all subsig of a sig is well covered, i.e.,
		// the dnf_step is increasing, it starts from 0 and its
		// last step is equal to dnf_count.
		// NOTE that the validity of v_dnf_step, ... columns are proved
		// already via v_sid columns in step 1.
		//
		// COST: 6n + 3
		check_eq(&v_sigs[0], &zero, "we require one dummy entry at begin")?;
		for i in 1..n{
			let b_new_row = v_sigs[i].is_neq(&v_sigs[i-1])?;
			let i_new_row: FpVar<F> = b_new_row.into();
			let res = (&i_new_row-&one) * &(//if this is NOT new row then:
				//(a) id_increase by one
				//ignore the case for v_sigs[i]==0
				&(&v_dnf_step[i] - &v_dnf_step[i-1] - &one) * &v_sigs[i]
			) + &i_new_row * &(//if this is NEW row
				//(b) starts from 0
				&(&r1 * &v_dnf_step[i]) + 
				//(c) previous row_step equals to count (for previs sig)
				// note we added one here becaues row_step starts from 0
				// ignore the rule when v_sigs[i-1] is zero
				&(&(&v_dnf_step[i-1] +&one - &v_dnf_count[i-1]) * &v_sigs[i-1])
			);

			check_eq(&res, &zero, "fails well-formed check")?;
		}


		//2.2 build subsigs from (sig_id, real_subsig) and lookup
		// (subsig, False) in the (vec_subsig, vec_result) from the
		// previous gen_sytneshsis_subsig_result(). This is needed
		// as the structure of subsigs are different between the 
		// two components.
		//
		// COST: 8n
		let (_bit_part1, bit_part2) =
			utils::consts::current_bit_parts();
		let fac2 = new_const_var(&cs, F::from(1u64<<bit_part2) );
		let f_false = new_const_var(&cs, F::from(TriVal::False as u8));

		let f_unit = FpVar::<F>::constant(F::from(1u32<<read_global_config().range2_bit));
		let v_computed_subsig = v_sigs.iter().zip(v_real_subsigs.iter())
			.map(|(sig_id, real_subsig_id)| {
				sig_id*&fac2 + real_subsig_id
		}).collect::<Vec<FpVar<F>>>();

		let src = encode_cols_var_adv_better(
			&vec![&v_computed_subsig[..], &vec![f_false.clone(); n][..]],
			&vec![0,1], &f_unit
		);
		//pad (0,1) for dummy entry
		let inp_subsigs_cs = eval_res_combo_cs.lock().unwrap()
			.get_container("inp_subsig").unwrap().lock().unwrap().to_vec();
		let inp_subsigs_igc = if self.capacity.b_skip_igc { vec![] }
			else { eval_res_combo_igc.lock().unwrap()
			.get_container("inp_subsig").unwrap().lock().unwrap().to_vec() };
		let inp_subsigs = vec![&inp_subsigs_cs[..], &inp_subsigs_igc].concat();
		let subsig_result = synthesis_res_combo.lock().unwrap()
			.get_container("vec_subsig_final_res").unwrap()
			.lock().unwrap().to_vec();
		let pad_subsigs = [&inp_subsigs[..], &vec![zero][..]].concat();
		let pad_res = [&subsig_result[..], &vec![f_false][..]].concat();
		let dst = encode_cols_var_adv_better(
			&vec![&pad_subsigs[..], &pad_res[..]],
			&vec![0,1], &f_unit
		);
		let mtbl_lkup_res = discharge_sig_combo.lock().unwrap()
			.get_container("mtbl_lk_res").unwrap().lock().unwrap().to_vec();
		assert_logup(cs.clone(), &src, &dst, &mtbl_lkup_res, &r1)?;

		//3. show that inp_sigs is a subset of v_sigs (covered)
		// where we have proved all v_sigs are discharged
		//note: v_sigs is shown earlier
		// to have at least one dummy entry at beginning so that just in
		// case inp_sigs has 0 entry.
		//
		//COST: let n1 = num of sigs, n = num of subsigs
		// 2n1 + 3n
		let discharged_sigs = discharge_sig_combo.lock().unwrap()
			.get_container("discharged_sigs").unwrap().lock().unwrap().to_vec();
		let mtbl_sigs= discharge_sig_combo.lock().unwrap()
			.get_container("mtbl_sigs").unwrap().lock().unwrap().to_vec();
		assert_logup(cs.clone(), &discharged_sigs, &v_sigs, &mtbl_sigs, &r1)?;

		if b_perf{
			println!(" ### validate_discharge_sig_combo: sigs: {}, subsig: {}, cost: {}", self.capacity.sigs, self.capacity.subsigs_cs + self.capacity.subsigs_igc, cs.num_constraints()-nc);
		}
		Ok( () )

	}

}

impl <F:PrimeField + ColEle> SigmaGadget<F> for ComputeSigAdvGadget<F>{
	fn get_name(&self)->&str {"ComputeSigAdvGadget"}

	fn set_job_id(&mut self, job_id: usize){
		self.job_id = job_id;
	}
	fn get_job_id(&self)->usize{
		self.job_id
	}

	/// set the container cfg. This is only needed for those gadgets
	/// in SED approach
	fn set_container_cfg(&mut self, cfgs_context: std::sync::Arc<Vec<ContainerConfig>>, idx: usize){
		self.cfgs_context = Some(cfgs_context);
		self.my_idx_in_context = Some(idx);
	}

	fn get_container_config(&self)->ContainerConfig{
		self.get_container_cfg().unwrap()
	}

	/// Get the instructions for build its statement.
	/// NOTE: this is only needed for those used in SedGadgetMapper.
	/// Others are handled by legacy code in their gadget mapper.
	fn get_stmt_map_instructions(&self)->Vec<(i32, usize, usize, usize)>{
		let cfg = self.get_container_cfg().expect("container cfg not set!");
		let res = cfg.gen_stmt_map_instructions();
		res
	}

	/// return the sizes of inp/oup/data/failed_sigs/discharged_sigs
	/// to append to the
	/// buffer of GadgetMapper.
	fn get_to_add_size(&self)->(usize, usize, usize, usize, usize){
		let cfg = self.get_container_cfg().expect("container cfg not set!");
		let to_add = cfg.get_to_add_size();
		for i in 0..3 {assert!(to_add[i+1] == to_add[4+i]);}
		assert!(to_add[IDX_INP]==to_add[IDX_OUP]);
		(to_add[IDX_INP], to_add[IDX_OUP], to_add[IDX_DATA], 0, self.capacity.sigs)
	}

	fn est_cost(&self)->usize{
		//TODO: refine formula in real data later
		let est = self.capacity.get_pat_loc_len(true) * 1000
			+ self.capacity.get_pat_loc_len(false) * 1000;

		est
	}

	fn get_msg_size(&self) -> (usize, usize, usize, usize){
		let cfg = self.get_container_cfg().expect("container cfg not set!");
		let to_add = cfg.get_to_add_size();
		let stat_len = (IDX_WORD..IDX_SI_DATA+1).collect::<Vec<usize>>()
			.iter().map(|i| to_add[*i]).sum();
		//TODO: needs a separate container for msg3, and need to
		//determine msg2 then.
		(stat_len, 0, 2, 0)
	}

	fn gen_msg1(&self, _stmt_vec: &Vec<F>, _v_idx: &Vec<(usize,usize)>) 
		-> Vec<F>{
		vec![] // dummy
	}

	fn gen_msg3(&self, _stmt_vec: &Vec<F>, _stmt_idx: 
		&Vec<(usize,usize)>, 
		_msg1_vec: &Vec<F>, _idx_msg1: usize, _len_msg1: usize,
		_msg2_vec: &Vec<F>, _idx_msg2: usize, _len_msg2: usize) -> Vec<F>{
		vec![]
	}

	/// COST:
	/// n0: sigs
	/// n1: subsigs
	/// n2 is the StepQueue::vec_size() - max of subsig * avg_active_pat_subsig
	///     and ratio_pat * nlen (see validate_forward_step_queue for
	///     real data for n1)
	/// n3: scc table (perc_comp_subsigs * subsigs - <20% of subsigs)
	/// 6n1+5n2 + 35*n1 +  2*n0 + 16*n1 
	/// = 2*n0 + 57*n1 + 5n2
	/// roughly 58 * subsigs (usually subsigs <2k) => <100k
	fn assert_msg3(&self, i: usize, cs: ConstraintSystemRef<F>,
		wtns: &WitnessSigmaIR1CSVar<F>, wtns_cfg: &WitnessSigmaIR1CSConfig, 
		_word_id: FpVar<F>, _subseg_id: FpVar<F>,
		_virt_vals: &mut Vec<FpVar<F>>)
		-> Result<(), SynthesisError>{
		//1. retrive the statement instance and get all parts
		let cfg = self.get_container_cfg().expect("container cfg not set!");
		let stmt = Container::<FpVar<F>>::load_from(i, wtns_cfg, wtns, &cfg)?;
		let r1 = wtns.msg2[0].clone();
		let r2 = wtns.msg2[1].clone();

		//2. validate the eval of subsig based on step queue result
		//two instances (cs and igc)
		let eval_res_combo_cs = stmt.get_container("eval_res_combo_cs")?;
		self.validate_eval_subsig_by_sq_combo(&eval_res_combo_cs.lock().unwrap(),
			r1.clone(), r2.clone(), cs.clone())?;
		//skip mode: no igc eval container exists; empty placeholder
		//(the validators below gate their igc reads on b_skip_igc)
		let eval_res_combo_igc = if self.capacity.b_skip_igc {
			Container::<FpVar<F>>::new("eval_res_combo_igc")
		} else {
			let c = stmt.get_container("eval_res_combo_igc")?;
			self.validate_eval_subsig_by_sq_combo(&c.lock().unwrap(),
				r1.clone(), r2.clone(), cs.clone())?;
			c
		};

		//TODO: 
		//3. follow the logic of accepts_approx_pm_bounds in clamav.rs
		// compute (1) res for gen_regex, (2) res for counter_constraint
		// (3) result for subsig_count_constraint. Note that
		// SubsigInfoStore has the related info such as subsig_type, comp_op
		// comp_num and component_subsigs they are already in
		// lkup e.g., using (ID_MIN_REQUIRED, ID_COMP_NUM) we can
		// retrieve the related info. We handle the results in three 
		// separate tables. (as the last one has dynamic size).
		let synthesis_res_combo= stmt
			.get_container("synthesis_res_combo")?;
		self.validate_synthesis_subsig_combo(
			&eval_res_combo_cs.lock().unwrap(),
			&eval_res_combo_igc.lock().unwrap(),
			&synthesis_res_combo.lock().unwrap(), 
			r1.clone(), cs.clone()
		)?;

		//4. now evaluate all sigs and generate the list of sigs
		//which are DISCHARGED.
		let sig_res_combo= stmt.get_container("sig_res_combo")?;
		self.validate_discharge_sig_combo(
			&eval_res_combo_cs, 
			&eval_res_combo_igc, 
			&synthesis_res_combo, 
			&sig_res_combo, 
			r1.clone(), r2.clone(), cs.clone())?;

		Ok(())
	}

}

impl ComputeSigAdvCapacity{
	/// same as the function of DischargeAdvCapacity - looks like
	/// no better way of refactoring. Just dupplicate it here.
	pub fn get_pat_loc_len(&self, b_igc: bool)->usize{
		let basis_pats_in_trace = if b_igc {self.basis_pats_in_trace_igc}
			else {self.basis_pats_in_trace_cs};
		let perc_pats_expansion_rate = if b_igc {self.perc_pats_expansion_rate_igc}
			else {self.perc_pats_expansion_rate_cs};
		let pats_len = basis_pats_in_trace * perc_pats_expansion_rate / 100
			* self.max_nibble_len/10000;

		pats_len
	}

	/// compute the buffer size of subsig count constraint proof.
	/// Floored at 1: the table always needs a null sentinel row (row 0),
	/// so a dataset with no count constraints (perc_comp=0) still gets 1.
	pub fn get_scc_prf_size(&self)->usize{
		(self.perc_comp_subsigs * (self.subsigs_cs + self.subsigs_igc) / 100)
			.max(1)
	}
}

