		let capacity= DischargeAdvCapacity{
			res_small_cost: DischargeAdvCapacity::default_res_small(),
			max_nibble_len: 62,
			subsigs: 4,
			universe_subsigs: 4,
			avg_active_pats_per_subsig: 2,
			basis_pats_in_trace: 48*100, //48 percent
			perc_pats_expansion_rate: 150,
			b_aggressive: false,
			prod_pats_expansion: 48*100*150,
			wrap_keys: 0,
			qm_real_rows: 0,
		};
